import { conceptNodes } from "./data";
import type { Chapter, ConceptNode, VisualModel } from "./data";
import type { ConceptLab, MirrorSubject, SourceLink, SystemBook, TaxonomyGroup } from "./systemTypes";
import { book21Journeys } from "./book21journeys";

type Seed = {
  id: number;
  shortTitle: string;
  formalTitle: string;
  overview: string;
  thesis?: string;
  moves: Array<{ title: string; body: string }>;
  closer: Array<{ title: string; body: string }>;
  distinction: [string, string, string, string, string];
  misreading: string;
  reflection: string;
  audit: string[];
  nodes: string[];
  model: VisualModel;
};

const makeChapter = (seed: Seed): Chapter => ({
  id: seed.id,
  shortTitle: seed.shortTitle,
  formalTitle: seed.formalTitle,
  overview: seed.overview,
  reflection: seed.reflection,
  relatedNodes: seed.nodes,
  visualModel: seed.model,
  deep: {
    thesis: seed.thesis ?? seed.moves[0].body,
    context: seed.overview,
    moves: seed.moves,
    closeReading: seed.closer,
    distinction: {
      title: seed.distinction[0], firstLabel: seed.distinction[1], first: seed.distinction[2],
      secondLabel: seed.distinction[3], second: seed.distinction[4],
    },
    misreading: seed.misreading,
    observation: seed.reflection,
    selfAudit: seed.audit,
    sourceAnchor: `Book 21, ${seed.formalTitle}.`,
  },
});

const chain = (title: string, caption: string, items: Array<[string, string, "support" | "balance" | "warning"]>): VisualModel => ({
  kind: "chain", title, caption, items: items.map(([label, body, role]) => ({ label, body, role })),
});

const pair = (title: string, caption: string, items: Array<[string, string, "support" | "balance" | "warning"]>): VisualModel => ({
  kind: "pair", title, caption, items: items.map(([label, body, role]) => ({ label, body, role })),
});

const set = (title: string, caption: string, items: Array<[string, string, "support" | "balance" | "warning"]>): VisualModel => ({
  kind: "set", title, caption, items: items.map(([label, body, role]) => ({ label, body, role })),
});

export const book21Chapters: Chapter[] = [
  makeChapter({
    id: 1, shortTitle: "Four words, five meanings", formalTitle: "The opening of the book, and what heart, spirit, self and reason mean",
    overview: "Ghazali opens the second half of the Ihya with the heart, because the heart is what knows God. Then he clears up four words — heart, spirit, self and reason. Each has more than one meaning, and he says most mistakes in this subject come from mixing them up.",
    thesis: "A person's honour lies in being able to know God, and he knows God with his heart, not with any limb. Four words are used for that heart. Between them they have five meanings, and only one of those meanings is what this book is about.",
    moves: [
      { title: "Why begin with the heart", body: "Human beings stand above many other creatures for one reason. They are able to know God. That knowledge is their beauty and pride in this world, and their store in the next. They know God with the heart, not with a hand or an eye. The heart is what knows God, draws near to Him, works for Him and travels to Him. The limbs are only its followers and tools, used the way an owner uses a slave or a craftsman a tool." },
      { title: "What the heart is held to", body: "The heart is accepted by God when it is free of everything besides Him. It is veiled from Him when it is sunk in other things. It is the one that is called, spoken to and blamed. It succeeds when it purifies itself, and fails when it buries itself in dirt. The good that shows on the limbs is its light spreading outward. The wrong that shows on them is its darkness seeping out. Every jug, as the saying goes, pours out what is in it." },
      { title: "Know your heart, know your Lord", body: "Whoever knows his heart knows himself, and whoever knows himself knows his Lord. Whoever does not know his heart knows even less about anything else. Most people are ignorant of their own hearts. The Quran says that God “comes between a man and his heart”. He does it, Ghazali says, by stopping a person from watching his heart and seeing how it turns. It sinks at times to the level of devils, and rises at times to the angels near God. Whoever never watches his heart is among those the Quran describes: “They forgot God, so He made them forget themselves.”" },
      { title: "Why this book comes first", body: "The first half of the Ihya dealt with what the limbs do: worship and daily customs. The second half deals with what happens in the heart: the traits that destroy and the traits that save. Before that, Ghazali says, two books are needed. One explains the wonders of the heart. The next explains how to train it. He will explain the heart through examples and pictures, because its real secrets belong to the unseen world, and most minds tire before they reach them." },
      { title: "Heart: the organ and the reality", body: "The first word is heart. It has two meanings. One is the cone-shaped piece of flesh on the left side of the chest, with a hollow inside holding dark blood. That blood is the source of the body's spirit. Animals have this heart, and so does a dead body. Doctors study it, and it is part of the visible world. The second meaning is a subtle, God-given, spiritual reality. It is connected to the physical heart, and it is the real human being. It is what understands and knows. It is what God speaks to, questions, blames and punishes." },
      { title: "Where Ghazali stops", body: "Most people are puzzled about how this reality is connected to the physical heart. Is it like a quality in a body, a user with his tool, or something resting in a place? Ghazali will not explain it, for two reasons. The answer belongs to the knowledge of unveiling, while this book is about practice. And explaining it would mean revealing the secret of the spirit, which the Prophet did not speak about. So he describes the heart's qualities and states, which practice needs, not what it is in itself." },
      { title: "Spirit: the vapour and the command", body: "The second word is spirit. One meaning is a fine vapour. It rises from the hollow of the physical heart and spreads through the pulsing veins to the whole body. Life, feeling, sight, hearing and smell flow from it into the limbs. It is like a lamp carried round the corners of a house: every wall it reaches lights up. Life is the light on the walls, and the spirit is the lamp. Doctors mean this vapour when they say spirit. The second meaning is the same knowing reality described above. The Quran means it when it says: “Say: the spirit is from the command of my Lord.” It is a wonderful thing from God, and most minds cannot grasp what it is." },
      { title: "Self: the enemy, and you", body: "The third word is self (nafs). One meaning is whatever gathers up anger and desire in a person. Sufis usually use it this way, for the source of all blameworthy traits. That is the self they say must be fought and broken. The Prophet pointed to it: “Your worst enemy is your self between your two sides.” The second meaning is the real person, the knowing reality itself. It gets different names in different states. When it rests under God's command, free of the pull of desires, it is “the self at peace”. God says: “O self at peace, return to your Lord, pleased and pleasing.” When it is not yet at rest, but pushes back against desire and blames its owner for falling short, it is “the self that blames”. When it stops resisting and obeys desire and the devil, it is “the self that urges evil”." },
      { title: "Reason: knowledge, or the knower", body: "The fourth word is reason ('aql). One meaning is knowledge of how things really are, a quality that lives in the heart. The other is the one who knows, the heart itself. A knower is one thing, and his knowledge is a quality in him. When the Prophet said, “The first thing God created was reason,” he meant the knower. Knowledge is a quality and could not be created first. And God spoke to it: “Come forward,” and it came; “Go back,” and it went back. So there are four words and five meanings. The physical heart, the physical spirit, the desiring self and knowledge are four. The fifth is the knowing reality, and all four words can point to it." },
    ],
    closer: [
      { title: "Why the mix-up matters", body: "Many scholars speak of thoughts and say: this is a thought from reason, this one from the spirit, this from the heart, this from the self. Their listeners cannot tell what is meant, because the words overlap. Wherever the Quran and the Prophet's practice say heart, they mean the part of a person that understands and knows the truth of things." },
      { title: "The throne and the footstool", body: "The knowing reality uses the whole body, but its first link is with the physical heart, as if that were its seat and kingdom. So Sahl al-Tustari said the heart is the throne and the chest the footstool. He did not mean they are God's throne and footstool, which is impossible. He meant that the heart is a person's kingdom, where his rule starts, as the throne and footstool are to God. Even that comparison only holds in some ways, and Ghazali leaves it there." },
    ],
    distinction: ["Two meanings of self", "The self to be fought", "The gathering of anger and desire — blamed completely, and on the devil's side.", "The self you are", "The real person — at peace, blaming, or urging evil, according to its state."],
    misreading: "Do not read the three names of the self as three selves. They are one person in three states. The self that blames is already a step above the self that simply gives in.",
    reflection: "Next time you hear heart, spirit, self or reason, ask which of the five meanings is meant.",
    audit: ["Do I ever watch how my heart turns?", "When I say I am fighting myself, which self do I mean?", "Does my conscience still blame me when I fall short?", "What shows on my limbs from my heart?"],
    nodes: ["heart", "self"],
    model: chain("Four words, five meanings", "Each word has two meanings. One of them is shared.", [["Heart", "The organ in the chest — or the knowing reality.", "balance"], ["Spirit", "The vapour carrying life — or the knowing reality.", "balance"], ["Self", "The gathering of anger and desire — or the knowing reality.", "warning"], ["Reason", "Knowledge — or the knowing reality that holds it.", "balance"], ["The fifth meaning", "The real person: the one who knows, is addressed and is held to account.", "support"]]),
  }),
  makeChapter({
    id: 2, shortTitle: "The heart's armies", formalTitle: "The armies of the heart: the seen and the unseen",
    overview: "The heart rules two armies. One is seen with the eyes: hands, feet, eyes, tongue. The other is seen only by insight: desire, anger, the senses, and five inner powers in the brain. Ghazali shows why each is needed by asking what the heart's journey requires.",
    thesis: "The heart was made for a journey to God. The body is its mount, and knowledge is its provision. To look after the mount, it needs desire to bring in what helps, anger to push away what harms, and the senses to know which is which. Every army it has comes from that need.",
    moves: [
      { title: "Armies only God can count", body: "The Quran says: “None knows the armies of your Lord except Him.” God has armies in hearts, spirits and other worlds, and only He knows their number and nature. Ghazali will describe some of the heart's armies, the ones that matter here. The heart has two. One army is seen with the eyes. The other is seen only with insight. The heart is the king, and the armies are its servants and helpers." },
      { title: "The army you can see", body: "The seen army is the hand, the foot, the eye, the ear, the tongue and every limb, inside and out. All of them serve the heart and are put under it. They were made to obey it and cannot disobey or rebel. When it tells the eye to open, the eye opens. When it tells the foot to move, the foot moves. When it tells the tongue to speak, the tongue speaks." },
      { title: "Like the angels, but unaware", body: "The limbs obey the heart the way the angels obey God. The angels are made to obey: “They do not disobey God in what He commands, and they do what they are told.” There is one difference. The angels are aware of their obedience. An eyelid opens and closes at the heart's command, but it knows nothing of itself or its obedience." },
      { title: "Why it needs armies at all", body: "The heart needs these armies for the journey it was made for: the journey to God, crossing the stages until it meets Him. “I created jinn and humans only to worship Me.” The body is its mount, and knowledge is its provision. Good deeds are the means to gather that provision. A person cannot reach God without living in a body and passing through this world. The lower stage must be crossed to reach the further one. This world is the farm of the next. It is called dunya because it is the nearer (adna) of the two homes." },
      { title: "Food, defence and knowing", body: "So the heart must look after the body, its mount. It must bring in what suits the body, like food, and push away what would destroy it. For bringing in food it needs an inner army, desire, and an outer one, the hand and the limbs that fetch. For pushing away harm it needs an inner army, anger, and an outer one, the hand and foot that act on it. And someone who needs food gains nothing from wanting it unless he knows what food is. So for knowing he needs an inner army, the powers of sight, hearing, smell, touch and taste, and an outer one, the eye, ear and nose. Ghazali says the full wisdom of all this would fill many volumes. He touches on some of it in the Book of Gratitude." },
      { title: "Three kinds of inner army", body: "All the heart's armies come down to three kinds. The first drives and urges. It pushes either towards what helps, as desire does, or away from what harms, as anger does. This is called will. The second moves the limbs to reach those aims. This is called power, and it is spread through the body, above all in the muscles and tendons. The third perceives and gets to know things, like spies. It is sight, hearing, smell, taste and touch, each set in its own organ. This is called knowledge and perception. With each inner army goes an outer one: the limbs of fat, flesh, nerve, blood and bone, made as its tools. The power to grip is in the fingers, and the power to see is in the eye." },
      { title: "The five inner senses", body: "The perceiving army divides again. Part of it lives in outer dwellings: the five senses. Part of it lives in inner dwellings, the hollows of the brain, and these are also five. After seeing something, a person closes his eyes and still sees its image inside. That is imagination. The image stays with him because something keeps it: the guarding army, memory. Then he thinks about what he has kept, and joins one part to another. That is thinking. He recalls what he had forgotten and returns to it. That is recollection. And he gathers what all the senses bring into one picture, by a common sense shared between them. If God had not created these powers, the brain would be as empty of them as the hand and foot are." },
      { title: "Written for the strong, explained for the weak", body: "Explaining all this so that everyone can follow it takes many examples. A book like this is meant for strong readers and great scholars. But Ghazali says he will still try to make it clear to weaker readers by giving pictures, so that it comes within their reach. The pictures come next." },
    ],
    closer: [
      { title: "Only the unseen army", body: "Ghazali says he will not speak about the outer army, the limbs. They belong to the visible world. His subject is the other one, which the Quran calls “armies you did not see”." },
      { title: "What the journey explains", body: "Every power the heart has is explained by the journey. Desire is not there by accident, and neither is anger. Each was given because a traveller with a body needs it to reach the end of the road." },
    ],
    distinction: ["Two armies", "The seen army", "Hands, feet, eyes, tongue — obedient without knowing they obey.", "The unseen army", "Desire, anger, the senses and the five inner powers, seen only by insight."],
    misreading: "Do not read desire and anger as mistakes in the design. Ghazali says they were made because the heart's journey needs them. The question is only whom they serve.",
    reflection: "Take one thing you did today and trace it back: which inner army moved it, and which outer army carried it out?",
    audit: ["Is my body a mount for a journey, or the destination?", "Which of my armies obeys me least?", "Do I use my senses as spies for the heart, or for desire?", "What provision am I gathering?"],
    nodes: ["heart", "appetite", "anger", "senses"],
    model: set("The heart's inner armies", "Three kinds, each with an outer tool.", [["Will", "Desire draws in what helps; anger pushes away what harms.", "balance"], ["Power", "Moves the limbs, spread through muscles and tendons.", "support"], ["Knowledge", "Five outer senses and five inner powers in the brain.", "support"]]),
  }),
  makeChapter({
    id: 3, shortTitle: "King, frontier, rider", formalTitle: "Three pictures of the heart with its inner armies",
    overview: "Desire and anger can obey the heart and help it on its way, or rebel and take it over. Ghazali gives three pictures to show both. The first is a king with his minister, his supplier and his police chief. The second is a soldier guarding a frontier fort. The third is a hunter on horseback with his dog.",
    thesis: "The heart has a third army, knowledge and wisdom, which is God's party against the other two. When the heart uses reason to rule desire and anger, they serve it. Most people do the opposite: their reason works for their desires, finding ways to satisfy them.",
    moves: [
      { title: "Obedient or rebellious", body: "The two armies of anger and desire can obey the heart completely. Then they help it on its road and are good company on the journey. Or they can rise against it in revolt, until they own it and make it their slave. That is its ruin, and it cuts it off from the journey to lasting happiness. The heart has another army: knowledge, wisdom and thought. It should call on this army for help, because it is God's party. The other two can go over to the devil's party." },
      { title: "Most people's state", body: "If the heart gives up calling on that army and hands itself over to anger and desire, it will certainly perish. That is the state of most people. Their reason has become a slave to their desires, busy inventing ways to satisfy them. It should be the other way round: desire should serve reason in whatever reason needs." },
      { title: "The first picture: the king", body: "The self in the body is like a king in his city. The body is his kingdom. The limbs and powers are its craftsmen and workers. The power of reason and thought is his sincere adviser and wise minister. Desire is like a bad slave who brings food and supplies into the city. Anger is like the chief of police." },
      { title: "The lying supplier", body: "The slave who brings the supplies is a liar and a cheat. He comes dressed as a well-wisher, but under his advice lies terrible harm and deadly poison. His habit is to argue with the minister over every plan, and he never stops for an hour. A wise king consults his minister and ignores the slave. In fact he takes the slave's advice as a sign that the right course is the opposite. He has his police chief discipline the slave, and puts the police under the minister's orders. Then the slave is managed, not managing. The city is in order, and justice runs through it." },
      { title: "The self does the same", body: "In the same way, the self is well ordered when it calls on reason for help. It disciplines itself with the heat of anger, and sets that anger on desire. It uses one against the other. Sometimes it cools anger by going against desire and drawing it along. Sometimes it crushes desire by turning anger on it and seeing its demands as ugly. Then its powers are balanced and its character good. Whoever leaves this path is the one the Quran describes. “Have you seen the one who takes his desire as his god, and God has sent him astray despite his knowledge?” And: “He followed his desire. He is like a dog: if you drive it off, it pants, and if you leave it, it pants.” But of the other it says: “As for the one who feared standing before his Lord and held himself back from desire, the Garden is his home.”" },
      { title: "The second picture: the frontier", body: "The body is like a city, and reason, the knowing part, is the king who runs it. The senses, outer and inner, are his soldiers and helpers, and the limbs are his subjects. The self that urges evil, meaning desire and anger, is an enemy fighting him for his kingdom and trying to destroy his people. So his body is like a frontier fort, and he is the soldier posted there. If he fights his enemy and defeats him, he is praised when he returns to the King's presence. God says: “God has raised those who strive with their wealth and their lives a level above those who stay behind.”" },
      { title: "The bad shepherd", body: "If he neglects his post and lets his people go, he is blamed, and God takes him to account. On the Day of Resurrection he will be told: “Bad shepherd! You ate the meat and drank the milk. You did not bring back the stray or set the broken leg. Today I take My due from you.” This is the sense of the saying, “We have come back from the lesser struggle to the greater struggle.”" },
      { title: "The third picture: the hunter", body: "Reason is like a hunter on horseback. His desire is his horse, and his anger is his dog. When the rider is skilled, the horse broken in and the dog trained, he is likely to succeed. When the rider is clumsy, the horse bolts and the dog bites wildly. Then the horse will not move under him when he wants, and the dog will not run at his signal. He is more likely to be killed than to catch anything. The rider's clumsiness is a person's ignorance, lack of wisdom and dull insight. The bolting horse is desire taking over, above all the desire of the stomach and of sex. The biting dog is anger taking over." },
    ],
    closer: [
      { title: "The slave's advice as a signpost", body: "The wise king does not just ignore the lying supplier. He treats his advice as a sign that the right course lies the other way. Ghazali builds the same move into the self: when desire urges strongly, that alone is a reason to check the opposite." },
      { title: "Used against each other", body: "In all three pictures, desire and anger are not thrown away. The police chief, the horse and the dog are all needed. Anger is used to break desire, and desire to calm anger. Their training, and how to set one against the other, is the subject of the next book, on training the self." },
    ],
    distinction: ["The same city, two rulers", "Reason in charge", "The minister advises, the police discipline the supplier, and justice runs through the city.", "Desire in charge", "The minister spends his cleverness finding ways to feed the supplier."],
    misreading: "Do not read these pictures as a call to kill desire and anger. The king needs his supplier and his police, and the hunter needs his horse and dog. What must change is who gives the orders.",
    reflection: "Think of a recent choice. Was your reason the minister, or the slave's secretary?",
    audit: ["Does my reason serve my desires, or rule them?", "Do I treat a strong urge as a reason to check the opposite?", "Is my horse broken in, or does it bolt?", "Am I guarding my frontier, or have I left it?"],
    nodes: ["intellect", "appetite", "anger"],
    model: chain("The king's household", "The first picture, in order of command.", [["King", "The self, ruling the body's city.", "support"], ["Minister", "Reason, the sincere adviser.", "support"], ["Police chief", "Anger, meant to serve the minister.", "balance"], ["Supplier", "Desire: a lying slave who must be managed, not obeyed.", "warning"]]),
  }),
  makeChapter({
    id: 4, shortTitle: "What only humans have", formalTitle: "What is special to the human heart: knowledge and will",
    overview: "Animals share everything described so far: desire, anger and the senses. Ghazali asks what the human heart has that they lack. His answer is knowledge and will. He shows how both grow in a child, how far they can climb, and why a person who wastes them sinks below the animals.",
    thesis: "What makes the human heart special is knowledge of things beyond the senses, and a will that follows reason even against desire. Knowledge of God is the highest of all. Whoever uses his body and powers for knowledge and action becomes like the angels; whoever serves bodily pleasure sinks to the level of beasts.",
    moves: [
      { title: "What animals share", body: "Everything described so far God has also given to animals. They have desire and anger, and outer and inner senses. A sheep sees a wolf with its eyes and knows with its heart that the wolf is its enemy, so it runs. That is inner perception. So what is special to the human heart, the thing that makes it noble and fit to come near God? Ghazali says it comes back to two things: knowledge and will." },
      { title: "Knowledge beyond the senses", body: "The first is knowledge of this world, the next world and truths grasped by reason. These lie beyond what the senses reach, and animals have no share in them. Take a simple truth: one person cannot be in two places at the same moment. A human judges this about every person. But his senses have only ever met a few people. So his judgment goes beyond anything his senses gave him. If this is clear for simple, obvious knowledge, it is even clearer for knowledge gained by thinking." },
      { title: "A will that can go against desire", body: "The second is will. When reason sees where something leads and what is good in it, a longing rises in the person to reach that good and take the means to it. This is not the will of desire, or the will animals have. It can go against desire. Desire shrinks from bloodletting and cupping; reason wants them and pays for them. Desire leans towards rich food during illness; a sensible person feels something in himself holding him back. That check does not come from desire. If God had created reason, which sees where things lead, without this drive to move the limbs by its verdict, reason's verdict would be wasted." },
      { title: "Two stages in a child", body: "Animals lack this knowledge and will. So does a newborn child; it appears only after he comes of age. A child already has desire, anger and the senses. Knowledge comes in two stages. In the first, his heart holds the obvious truths: what is impossible, and what is plainly possible. Knowledge gained by thinking is not there yet, but it is close. He is like someone learning to write who knows the pen, the inkpot and the single letters, but cannot yet join them. In the second, he has gathered knowledge by experience and thought. It is stored in him, and he can return to it when he likes. He is like a skilled writer, who is called a writer even when he is not writing. This is the height of being human." },
      { title: "Levels without number", body: "Within that height there are countless levels. People differ in how much they know, and in how noble the things they know are. They also differ in how knowledge reaches them. Some hearts receive it by divine inspiration, all at once, by unveiling. Others receive it by learning and effort. For some it comes quickly, for others slowly. Here the levels of scholars, sages, prophets and friends of God part ways. The climb has no end, because what God knows has no end." },
      { title: "The prophet at the top", body: "The highest level is the prophet's. Most or all truths are unveiled to him, without effort or study, by divine unveiling in the shortest time. By this happiness a person comes near God — in meaning, reality and quality, not in place or distance. The steps of this climb are the stages of those travelling to God, and they have no number. Each traveller knows the stage he has reached and the ones behind him. What lies ahead he cannot fully grasp, though he may believe in it, as we believe in prophecy without knowing what it is from inside. An unborn child does not know the state of an infant, or an infant the state of a child who can tell things apart. That child does not know the state of a grown thinker. In the same way, the thinker does not know what God opens to His friends and prophets." },
      { title: "The mercy is not withheld", body: "That mercy is given freely, out of God's generosity, and held back from no one. It shows only in hearts that put themselves in its way, by cleaning off the dirt of bad character. The Prophet said: “Your Lord has breezes of mercy in the days of your time. Put yourselves in their way.” He said that God comes down every night to the nearest heaven and says: “Is there anyone calling, that I may answer him?” He reported God as saying: “The longing of the righteous to meet Me has grown long, and I long to meet them even more.” And God says: “Whoever comes near Me a hand's span, I come near him an arm's length.”" },
      { title: "Full jugs", body: "All of this shows that the lights of knowledge are not kept from hearts because the Giver is mean. God is far above meanness. They are kept out by the dirt, murk and busyness of the hearts themselves. Hearts are like jugs. As long as a jug is full of water, air cannot get in. A heart busy with other than God has no room for knowing Him. So the Prophet said: “If the devils did not hover around the hearts of Adam's children, they would look upon the unseen kingdom of heaven.” So what is special to a human being is knowledge and wisdom. The noblest knowledge is of God, His attributes and His acts. In it lies a person's perfection, and in that perfection his happiness and fitness to be near God. The body is the self's mount, the self is the home of knowledge, and knowledge is what a human being was made for." },
      { title: "The horse and the donkey", body: "A horse shares the donkey's strength to carry loads. But it has something extra: speed in attack and retreat, and a fine form. It was made for that extra. If it loses it, it sinks to the donkey's level. A human shares much with animals and plants. As something that eats and has children, he is a plant. As something that feels and moves by choice, he is an animal. His shape and height are like a figure painted on a wall. What is his alone is knowing how things really are, and that is a quality of the angels. Whoever uses all his limbs and powers to help him towards knowledge and action has become like the angels. He deserves to join them and to be called an angel, as the women said of Joseph: “This is no human. This is a noble angel!” Whoever turns his effort to bodily pleasures, eating as cattle eat, has sunk to the lowest level of the beasts. He becomes dull like an ox, greedy like a pig, snapping like a dog or a cat, or grudging like a camel. He may become proud like a leopard or sly like a fox. Or he gathers all of these, like a rebel devil. Every limb and every sense can help on the way to God. Whoever uses it for that has won; whoever turns it aside has lost." },
    ],
    closer: [
      { title: "The king's household, again", body: "Happiness, Ghazali sums up, is to make meeting God your aim and the next world your home. This world is your stopping place, the body your mount and the limbs your servants. The knowing self sits in the heart like a king. Imagination, in the front of the brain, is its postmaster, where the news of the senses gathers. Memory, in the back of the brain, is its treasurer. The tongue is its interpreter, the moving limbs its scribes, and the five senses its spies. Each spy is posted to one province: the eye to colours, the ear to sounds, the nose to smells. Ka'b al-Ahbar gave the same picture to Aisha. He said: “A person's eyes are guides, his ears funnels, his tongue an interpreter, his hands wings, his feet messengers, and his heart the king.” She said she had heard the Prophet say the same." },
      { title: "Hearts as vessels", body: "Ali said: “God has vessels on His earth, and they are hearts. The dearest to Him are the gentlest, the clearest and the firmest.” He explained: firmest in religion, clearest in certainty, gentlest towards brothers. Ubayy ibn Ka'b read the verse of light — “like a niche with a lamp in it” — as the light of the believer's heart. The verse of darkness on a deep sea describes the hypocrite's heart. Zayd ibn Aslam read “a preserved tablet” as the believer's heart. These, Ghazali says, are the pictures of the heart." },
    ],
    distinction: ["Two kinds of will", "The will of desire", "Shared with animals; shrinks from bitter medicine and leans to rich food when ill.", "The will that follows reason", "Only human; wants the cure and holds back from the harm, even against desire."],
    misreading: "Do not read the prophet's level as the only one that matters. Ghazali says the climb has countless levels, and God's mercy is held back from no one who puts himself in its way.",
    reflection: "Name one thing you are sure of that your senses could never have shown you. That, Ghazali says, is where you differ from the animals.",
    audit: ["What am I using my limbs for today?", "Does my will ever follow reason against desire?", "Am I putting myself in the way of God's breezes of mercy?", "Which animal's trait shows in me most?"],
    nodes: ["heart", "knowledge", "intellect"],
    model: chain("The climb of knowledge", "From the womb to the prophet, the levels have no end.", [["The unborn child", "Cannot imagine the infant's world.", "balance"], ["The child", "Knows the obvious truths, like a writer who knows only the letters.", "balance"], ["The grown thinker", "Has knowledge stored, like a skilled writer.", "support"], ["The friends of God", "Receive what the thinker cannot picture.", "support"], ["The prophet", "Truths unveiled without effort, in the shortest time.", "support"]]),
  }),
  makeChapter({
    id: 5, shortTitle: "Pig, dog, devil, sage", formalTitle: "The four kinds of trait gathered in the heart, and how they mark it",
    overview: "Four kinds of trait are mixed into every person: those of the wild beast, the grazing animal, the devil and the lordly. Ghazali turns them into a picture: under one skin live a pig, a dog, a devil and a sage. Whichever rules leaves its traits on the heart, polishing it or blackening it.",
    thesis: "Every person carries a pig, which is desire; a dog, which is anger; a devil, which stirs them both; and a sage, which is reason. If the sage rules, the heart fills with noble traits and shines. If it serves the other three, the person spends his day worshipping them, and their traits pile up on the heart until it is sealed.",
    moves: [
      { title: "Four mixtures", body: "A human being was made with four mixtures, so four kinds of trait come together in him. Where anger rules him, he acts like a beast of prey: hostility, hatred, attacking people with blows and insults. Where desire rules him, he acts like a grazing animal: gluttony, greed and lust. Because he is himself something from God's command — “the spirit is from the command of my Lord” — he claims lordship for himself. He loves to dominate and rise above others. He wants everything for himself, to rule alone, and to slip the rope of servanthood and humility. He wants to know everything, claims to understand how all things are, is pleased to be called learned and hurt to be called ignorant. Knowing all truths and ruling all creatures by force are qualities of Lordship, and humans are greedy for them. Humans differ from animals in being able to tell things apart. But they share anger and desire with them. From that mix comes something devilish. A person becomes wicked and uses his judgment to find ways of doing harm. He reaches his aims by cunning, tricks and deceit, and dresses evil up as good. These are the manners of devils. Every person has some of all four: the lordly, the devilish, the beastly and the animal. All of them are gathered in the heart." },
      { title: "Four under one skin", body: "It is as if four live under one human skin: a pig, a dog, a devil and a sage. The pig is desire. A pig is not blamed for its colour or shape, but for its greed and craving. The dog is anger. A savage beast or a biting dog is what it is because of its fierceness and aggression, not its shape or colour. Inside a person are the fierceness and rage of the beast, and the greed and lust of the pig. The pig calls, through greed, to indecency and wrong. The beast calls, through anger, to injustice and harm. The devil never stops stirring up the pig's craving and the beast's rage. He sets one on the other, and makes what each was made for look good." },
      { title: "The sage's task", body: "The sage stands for reason. He is told to push back the devil's plots by exposing his tricks with sharp insight and clear light. He is to break the pig's greed by setting the dog on it, since anger breaks the force of desire. And he is to check the dog's fierceness by setting the pig on it, keeping the dog under his rule. If he does this, things come into balance. Justice appears in the kingdom of the body, and everything runs on the straight path. If he cannot master them and they master him, they put him to work. He spends all his time inventing tricks and sharpening his thinking to feed the pig and please the dog. He is always worshipping a dog and a pig." },
      { title: "The idol-worshipper who mocks idols", body: "That is the state of most people, whose main concern is stomach, sex and getting the better of rivals. The strange thing is that such a person looks down on idol-worshippers for worshipping stones. If the cover were lifted, he would see himself as he really is. Those who are shown hidden things see it in sleep or waking. He would see himself standing before a pig, bowing down to it, now prostrating, now waiting for its signal. Whenever the pig stirs for something it wants, he rushes to serve it. Or he would see himself standing before a biting dog, worshipping it, listening for its orders and working out how to obey. All the while he pleases his devil, who stirs the pig and rouses the dog. So through them he worships the devil. Each person, Ghazali says, should watch his movements and his stillness, his silence and his speech, his standing and his sitting. If he is fair with himself, he will see that he spends the whole day serving these three. That is the worst injustice. The owner has become the owned, the master the slave, and the ruler the ruled. Reason should be in charge, and he has made it serve these three." },
      { title: "What each master leaves behind", body: "Obeying them leaves traits on the heart, which pile up until they become a seal and rust that kill it. Serving the pig of desire leaves shamelessness and foulness, wastefulness and stinginess. It leaves showing off, recklessness, frivolity and idle play, greed and craving, flattery, envy, spite and gloating. Serving the dog of anger leaves rashness, crudeness and swagger, conceit and flying into rages. It leaves arrogance and vanity, mockery, belittling people, wanting to hurt, and a taste for injustice. Serving the devil through desire and anger leaves cunning, deceit, trickery and slyness. It leaves boldness in wrong, confusing the truth, stirring up trouble, cheating, double-dealing and foul speech." },
      { title: "What the sage's rule leaves behind", body: "If the order is reversed, and all of them are brought under the lordly trait, the heart settles into lordly qualities. These are knowledge, wisdom and certainty, grasping things as they really are, mastering all by the power of knowledge, and deserving to lead because of it. Such a person no longer needs to worship desire and anger. Holding the pig of desire to its proper measure gives him chastity and contentment. It also gives calm, doing without, caution about the doubtful, mindfulness of God, cheerfulness, dignity of bearing, modesty, grace and helpfulness. Holding anger to its due measure gives him courage, generosity and gallantry. It also gives self-control, patience and forbearance, putting up with others, forgiveness, steadiness, nobility, high spirit and gravity." },
      { title: "Smoke on the mirror", body: "The heart is like a mirror surrounded by all these, and their marks reach it without pause. The good marks make it brighter and clearer, until the truth shines in it and what is sought in religion is unveiled. Of such a heart the Prophet said: “When God wants good for someone, He gives him a preacher from his own heart.” In this heart remembrance settles: “Truly, in the remembrance of God hearts find rest.” The bad marks are like dark smoke rising to the mirror. It piles up layer on layer until the heart goes black and is completely veiled from God. That is the seal and the rust: “No! What they used to earn has rusted over their hearts.”" },
      { title: "Breath on the glass", body: "Obeying God against desire polishes the heart, and disobeying Him blackens it. Someone who follows a bad deed with a good one, wiping out its trace, does not go dark. But his light is lessened. He is like a mirror someone breathes on and wipes, then breathes on and wipes again. It is never quite free of mist. A good deed after a sin only brings the heart back to where it was. Had the good deed come with no sin before it, the heart would have grown brighter. A mirror dirtied and then wiped is not like one polished to make it clearer still. That lost gain is a real loss, and nothing can make it up." },
      { title: "Four hearts", body: "The Prophet said there are four kinds of heart. One is bare, with a lamp shining in it: the believer's heart. One is black and upside down: the unbeliever's heart. One is wrapped and tied in its cover: the hypocrite's heart. And one is two-faced, with faith and hypocrisy both in it. The Quran ties deafness to sins as it ties hearing to mindfulness of God. “If We willed, We would strike them for their sins and seal their hearts, so they do not hear.” And: “Be mindful of God and listen.” And: “Be mindful of God, and God will teach you.”" },
    ],
    closer: [
      { title: "The black spot", body: "Maymun ibn Mihran said: when someone sins, a black spot is marked on his heart. If he stops and repents, it is polished away. If he returns to it, it spreads until it covers the heart. That is the rust. The Prophet said: “The believer's heart is bare, with a lamp shining in it. The unbeliever's heart is black and upside down.” Faith in the heart is like a green plant fed by good water. Hypocrisy is like an ulcer fed by pus. Whichever supply wins decides the heart's state. When sins pile up, the heart goes blind to the truth. It makes light of the next world and much of this one. Talk of the next world goes in one ear and out the other, and does not move it to repent." },
      { title: "The key to the door", body: "The Quran says: “When those who are mindful of God are touched by a prowler from the devil, they remember — and at once they see.” So the heart's clearing and sight come through remembrance, and only the mindful reach it. Mindfulness is the door to remembrance. Remembrance is the door to unveiling. Unveiling is the door to the greatest success: meeting God." },
    ],
    distinction: ["Two masters, two sets of traits", "The sage in charge", "Chastity, contentment, courage, forbearance, forgiveness — and a mirror growing brighter.", "The pig and the dog in charge", "Greed, envy, arrogance, spite, cunning — and smoke building up until the mirror is black."],
    misreading: "Do not read the pig and the dog as insults for other people. Ghazali says all four live under every person's skin, and asks each reader to watch his own day.",
    reflection: "Watch yourself for one day as Ghazali asks. Count how much of it served the pig, the dog or the devil.",
    audit: ["Whom did I serve today — the sage, or the other three?", "Which traits are piling up on my heart?", "Do I look down on others for a worship I share?", "When I sin, do I polish the spot, or let it spread?"],
    nodes: ["appetite", "anger", "devil", "mirror"],
    model: set("Four under one skin", "One person, four kinds of trait.", [["The pig", "Desire: greed, craving, shamelessness.", "warning"], ["The dog", "Anger: fierceness, arrogance, wanting to hurt.", "warning"], ["The devil", "Stirs both, and dresses evil as good.", "warning"], ["The sage", "Reason: sets the dog on the pig and the pig on the dog, and keeps both under rule.", "support"]]),
  }),
  makeChapter({
    id: 6, shortTitle: "The mirror and its five blocks", formalTitle: "The heart compared to a mirror, with respect to knowledge in particular",
    overview: "The heart is where knowledge lives, and Ghazali compares it to a mirror. Knowing something is its true picture appearing there. A mirror can fail to show a picture for five reasons, and so can a heart. Yet every heart, by its nature, is fit to know the truth: it is what carried the Trust that the heavens refused.",
    thesis: "Every heart is made ready to reflect the truth of all things. When it does not, there are only five reasons. It is unfinished or rusty. It faces the wrong way, a curtain hangs in front of it, or it does not know where to look.",
    moves: [
      { title: "Three things, not one", body: "The home of knowledge is the heart, the subtle reality that runs the limbs. It stands to the truths of things as a mirror stands to coloured objects. An object has a form, and a likeness of that form appears in the mirror. In the same way, everything that can be known has a reality, and a likeness of that reality appears in the heart. The mirror is one thing, the person is another, and the likeness in the mirror is a third. So here too there are three: the heart, the truths of things, and those truths being present in the heart. The knower is the heart. The known is the truth of things. Knowledge is the likeness arriving in the mirror." },
      { title: "The hand and the sword", body: "Holding needs a holder, like a hand, and something held, like a sword. When the sword arrives in the hand, that is called holding. Before that, the hand existed and the sword existed, but there was no holding. So too the truth existed and the heart existed, but there was no knowledge until the truth arrived in the heart. There is one difference. When you hold a sword, the sword itself is in your hand. When you know fire, fire itself does not arrive in your heart. What arrives is its definition and reality, matching its form. That is why the mirror is the better picture. A person does not enter a mirror; only a matching likeness does." },
      { title: "The first two blocks", body: "A mirror fails to show a picture for five reasons. The first is that it is not finished, like iron before it is shaped and polished. The second is that it is dirty, rusty and dull, though fully shaped. So it is with the heart. The first block is a lack in the heart itself, as with a child's heart, where things do not yet show. The second is the murk of sins and the grime that piles up on the heart from many desires. That stops it being clear, so the truth cannot show in its darkness. The Prophet pointed to this: “Whoever commits a sin, some reason leaves him and never returns.” Ghazali explains: a mark stays that never fully goes. The most a person can do is follow the sin with a good deed that wipes it out. But had the good deed come without the sin, the heart would have grown brighter. So the sin cost him that gain for good." },
      { title: "What polishes it", body: "Turning to obey God and away from the pull of desire is what polishes the heart and makes it clear. So God says: “Those who strive for Us, We will surely guide them to Our paths.” And the Prophet said: “Whoever acts on what he knows, God gives him knowledge of what he did not know.”" },
      { title: "The third block: facing away", body: "The third reason is that the mirror is turned away from the thing it should show, as when the thing is behind it. A heart can be pure and obedient and still not see the truth clearly, because it is not looking for it. It is not facing what it wants to see. It may be wholly taken up with the details of bodily worship, or with arranging a living. It does not turn its thought to the presence of the Lord and the hidden divine truths. So nothing is unveiled to it except what it is thinking about. If it thinks about the hidden flaws in deeds and the secret faults of the self, those are shown to it. If it thinks about making a living, that is shown to it. If being taken up with the details of worship blocks the truth, what of someone taken up with worldly pleasures and ties?" },
      { title: "The fourth block: the curtain", body: "The fourth reason is a curtain. Someone may be obedient, master his desires and think only about one truth. It may still not be unveiled to him, because a belief blocks it. He took that belief on trust in childhood, out of good opinion of those who taught it. It stands between him and the truth, and stops anything opposite to it from appearing in his heart. Ghazali calls this a great veil. It blocks most theologians, and those who are partisan for their schools. It even blocks most good people who think about the kingdom of heaven and earth. Beliefs taken on trust have frozen in their selves, settled in their hearts, and become a curtain between them and the truth." },
      { title: "The fifth block: where to look", body: "The fifth reason is not knowing the direction in which the thing sought will be found. A student cannot learn something unknown except by recalling the things he knows that are related to it. He must arrange them in a particular order, which scholars call the ways of reasoning. Then he has found the direction, and the answer shows in his heart. Knowledge that is not inborn is only caught in the net of knowledge already held. Each new piece of knowledge comes from two earlier ones joined in a particular way, as offspring come from a male and a female. Someone who wants a mare cannot get one from a donkey, a camel or a human. It must come from a horse and a mare, paired in the right way. So every piece of knowledge has two particular roots and a particular way of joining them. Not knowing those roots, or how to join them, is what blocks knowledge." },
      { title: "The back of your head", body: "Ghazali's picture for the fifth block is someone who wants to see the back of his head in a mirror. If he holds the mirror in front of his face, it is not facing the back of his head, so the back of his head does not appear. If he holds it behind his head, it is no longer facing his eyes, so he sees neither the mirror nor the image. He needs a second mirror. One goes behind his head and one in front of his eyes, set at just the right angle to each other. Then the back of his head appears in the first mirror, the first mirror appears in the second, and his eye sees it. The ways of catching knowledge have twists and turns stranger than this. Hardly anyone on earth is guided to the trick of them." },
      { title: "Every heart is fit for it", body: "Apart from these five, every heart is by nature fit to know the truth of things. It is a noble thing from God, set apart from everything else in the world by this. God points to it: “We offered the Trust to the heavens, the earth and the mountains. They refused to carry it and were afraid of it, and the human being carried it.” So humans have something that sets them apart from heavens, earth and mountains, and lets them bear God's Trust. That Trust is knowing God and His oneness. Every human heart is ready for it and able to carry it. Only the five causes hold it back. So the Prophet said: “Every child is born on the natural way. It is his parents who make him a Jew, a Christian or a Magian.”" },
    ],
    closer: [
      { title: "Not a lack on God's side", body: "The five blocks are all on the heart's side. None of them is a meanness on God's side. That is why the fourth block, the belief taken on trust, is the hardest to see: it looks like the truth to the one who holds it." },
      { title: "The good who are blocked", body: "Ghazali puts the third and fourth blocks on people who worship much and people who study much. A clean mirror can face the wrong way, and a clean mirror can have a curtain in front of it. A good record elsewhere does not rule either out." },
    ],
    distinction: ["Two blocks in good people", "Facing away", "A pure heart busy with the details of worship or a living, not turned to the truth itself.", "The curtain", "A belief taken on trust in childhood, which now stops anything opposite from showing."],
    misreading: "Do not read the fourth block as an attack on holding beliefs. Ghazali's point is about a belief never looked at, which stops the heart seeing even when it is clean and looking.",
    reflection: "Pick one thing you have never been able to see clearly. Go through the five blocks and ask which one is in the way.",
    audit: ["Which of the five blocks is in my way now?", "What have my sins cost me that a good deed cannot give back?", "Which of my beliefs have I only ever defended, never checked?", "Do I know which two things I need to join?"],
    nodes: ["mirror", "knowledge", "veil"],
    model: chain("Why a mirror shows nothing", "Five reasons, and only five.", [["Unfinished", "Iron before it is shaped: the child's heart.", "balance"], ["Rusty", "The grime of sins and desires.", "warning"], ["Facing away", "A clean heart busy with other things, even good ones.", "balance"], ["Curtained", "A belief taken on trust and never checked.", "warning"], ["Lost", "Not knowing which two known things to join.", "balance"]]),
  }),
  makeChapter({
    id: 7, shortTitle: "What the clear heart sees", formalTitle: "The unseen kingdom shown in a clear heart, and three levels of faith",
    overview: "When the veil lifts, the heart sees the unseen kingdom, which is wider than the heavens and the earth. Ghazali says this seeing has levels. He shows three levels of faith with one simple example: knowing that Zayd is in the house.",
    thesis: "All worship aims at polishing the heart until the light of knowing God shines in it. Faith has three levels: believing on trust, believing with some evidence, and seeing for yourself. Even those who see differ in how clearly they see and how much.",
    moves: [
      { title: "Where is God?", body: "The devils hovering round the heart are some of the veils between hearts and the unseen kingdom. Ibn Umar reported that the Prophet was asked: “Where is God — on earth or in heaven?” He said: “In the hearts of His believing servants.” A report has God saying: “My earth and My heaven cannot hold Me. The heart of My believing servant, gentle and at ease, holds Me.” The Prophet was asked who is best among people. He said: “Every believer with a swept heart.” They asked what that meant. He said: “The mindful and pure, with no cheating in him, no wrongdoing, no treachery, no spite and no envy.”" },
      { title: "My heart saw my Lord", body: "So Umar said: “My heart saw my Lord.” He had lifted the veil by mindfulness of God. When the veil between someone and God is lifted, the form of the visible world and the unseen kingdom shines in his heart. He sees a Garden whose width is as the heavens and the earth. In fact the whole of it is wider than the heavens and the earth. The heavens and earth are the visible world. However vast, it has an end. The unseen kingdom, the secrets hidden from eyes and seen only by insight, has no end. What shows of it to one heart is limited. But in itself, and in God's knowledge, it is endless." },
      { title: "The Lord's presence", body: "The visible world and the unseen kingdom, taken together at once, are called the Lord's presence. That presence takes in everything that exists, because nothing exists except God, His acts and His kingdom, and His servants are among His acts. Some people say that what shows of this to the heart is the Garden itself. The people of truth say it is the cause of deserving the Garden. And a person's kingdom in the Garden will be as wide as his knowledge: as much as has shown to him of God, His attributes and His acts." },
      { title: "What worship is for", body: "The aim of all worship and all the work of the limbs is to clean, purify and polish the heart. “Whoever purifies it has succeeded.” The aim of purifying it is that the lights of faith appear in it, meaning the dawning of the light of knowing God. God says: “Whomever God wants to guide, He opens his chest to Islam.” And: “Is the one whose chest God has opened to Islam, so that he is on a light from his Lord…?” The Prophet was asked what that opening is. He said: “It is widening. When light is thrown into the heart, the chest widens for it and opens.”" },
      { title: "First level: on someone's word", body: "This faith has three levels. The first is the faith of ordinary people, which is pure trust. The second is the faith of theologians, mixed with some reasoning, and close to the first. The third is the faith of those who know God, seen by the light of certainty. Take believing that Zayd is in the house. At the first level, someone you have always found truthful tells you he is there. Your heart settles on his word alone. That is ordinary faith. When ordinary people come of age, they hear from their parents and teachers about God's existence, knowledge, will and power, His attributes, and the sending of the messengers. They accept it, hold to it and rest in it, out of good opinion of their parents and teachers." },
      { title: "Faith on trust saves", body: "This faith saves a person in the next life. Its people are among the first of the People of the Right Hand, though not among those brought near. It has no unveiling or insight in it, and no opening of the chest by the light of certainty. Error is possible in what is heard from others, whether few or many, when it comes to beliefs. The hearts of Jews and Christians also rest on what they hear from their parents. They believed what they believed wrongly, because error was handed to them. Muslims believed the truth, not because they saw it for themselves, but because the word of truth was handed to them." },
      { title: "Second level: his voice behind the wall", body: "At the second level, you hear Zayd's voice and speech from inside the house, from behind a wall. You conclude from it that he is there. Your belief is stronger than when you only heard it from someone. If you were told he is there and then heard his voice, your certainty would grow. That is faith mixed with evidence. Error is still possible. One voice can sound like another, and someone can imitate a voice on purpose. But the listener does not think of it, because he has no reason to suspect a trick." },
      { title: "Third level: seeing him", body: "At the third level, you go into the house and see Zayd with your own eyes. That is real knowledge and certain sight. It is like the knowing of those brought near and the truthful. They believe from sight, so their faith contains the faith of ordinary people and of theologians, with one clear advantage: no error is possible in it." },
      { title: "Even seers differ", body: "Those who see still differ, in how clearly they see and in how much. One sees Zayd close up, in the open courtyard, in bright sunshine, and sees him fully. Another sees him inside a room, or from far away, or at dusk. He is sure it is Zayd, but the fine details of his face do not appear to him. The same is true of seeing divine things. As for how much: one sees Zayd, Amr, Bakr and others in the house; another sees only Zayd. Knowing grows, without doubt, as the things known grow." },
    ],
    closer: [
      { title: "Why the Garden has sizes", body: "Ghazali ties the size of each person's kingdom in the Garden to how much of God was shown to his heart. That is why the lifting of the veil is not a curiosity. It is the measure of what a person will have in the next world." },
      { title: "Not despising the first level", body: "The first level is not treated as worthless. Ghazali says plainly that it saves. Its weakness is that it cannot tell a true report from a false one by itself, which is why Jews and Christians hold their beliefs just as firmly." },
    ],
    distinction: ["Two ways of being sure", "Hearing the voice", "Evidence from behind a wall — stronger than hearsay, but open to imitation.", "Seeing him", "Walking into the house — certainty with no room for error."],
    misreading: "Do not read the three levels as three religions. They are three ways of holding the same truth, and Ghazali says the first level already saves a person.",
    reflection: "Take one thing you believe about God. Ask whether you hold it on someone's word, on evidence, or by something you have seen for yourself.",
    audit: ["Is my faith trust, evidence or sight?", "What am I doing to widen my chest?", "Is my heart swept clean of spite and envy?", "Would my belief survive a clever imitation?"],
    nodes: ["mirror", "unseen", "knowledge"],
    model: chain("Zayd in the house", "Three levels of being sure.", [["Told", "A truthful person says he is there: the faith of ordinary people.", "balance"], ["Heard", "His voice behind the wall: faith mixed with evidence.", "balance"], ["Seen", "You walk in and see him: the knowing of those brought near.", "support"]]),
  }),
  makeChapter({
    id: 8, shortTitle: "Reason, revelation, two worlds", formalTitle: "The heart and the kinds of knowledge: rational and religious, worldly and otherworldly",
    overview: "The heart is made ready for all knowledge, but knowledge comes in kinds. Some is from reason, inborn or learned. Some is from the prophets. Some serves this world and some the next. Ghazali shows that reason and revelation need each other like food and medicine, and that this world and the next are like two rival wives.",
    thesis: "Reason cannot do without revelation, and revelation cannot be understood without reason. Whoever calls for pure acceptance with reason set aside is ignorant; whoever relies on reason alone is deceived. And the knowledge of this world and of the next usually crowds each other out.",
    moves: [
      { title: "Inborn and acquired", body: "The knowledge that settles in the heart is of two kinds: rational and religious. Rational knowledge is what the instinct of reason judges, not what is taken on trust or heard. It divides into the obvious and the acquired. Obvious knowledge comes without our knowing from where or how. One person cannot be in two places. One thing cannot be both new and eternal, or both exist and not exist. A person finds himself made with this knowledge from childhood, without knowing its near cause — though he knows God created him and guided him. Acquired knowledge comes by learning and reasoning. Both are called reason. Ali put it in verse: reason is of two kinds, the inborn and the heard. The heard is no use without the inborn, as the sun is no use to an eye that cannot see." },
      { title: "Two sayings to Ali", body: "The first kind is meant by the Prophet's words to Ali: “God created nothing more honoured by Him than reason.” The second is meant by his other words to Ali: “When people draw near to God by all kinds of good deeds, draw near by your reason.” No one can draw near to God by an instinct he was born with, or by obvious truths. It is done by knowledge that is earned. Someone like Ali could draw near by using his reason to catch the knowledge that brings a person close to God." },
      { title: "The eye and the sun", body: "The heart is like the eye, and the instinct of reason in it is like the power of sight. That power is lost in the blind and present in the seeing, even when their eyes are shut or it is night. The knowledge that comes to the heart is like the eye actually seeing things. Knowledge being late in a child, until he can tell things apart or comes of age, is like sight waiting for the sun to rise and light things. The pen by which God writes knowledge on the pages of hearts is like the disc of the sun. A child has no knowledge yet because the tablet of his heart is not ready to receive it. “He taught by the pen, taught the human what he did not know.” God's pen is not like the pens of His creatures, any more than He is like them. It is not reed or wood, just as God is neither a body nor a quality." },
      { title: "A blind rider", body: "The likeness between inner insight and outer sight holds in these ways. But there is no comparison in worth. Inner insight is the eye of the self, the knowing reality, and the self is like a rider and the body like a horse. A blind rider is worse off than a blind horse — in fact there is no comparing the two harms. That is why God calls the heart's knowing by the name of seeing: “The heart did not lie about what it saw.” And: “So We showed Abraham the kingdom of the heavens and the earth.” That was not seeing with the eyes, which was not special to Abraham. He calls its opposite blindness: “It is not the eyes that go blind, but the hearts in the chests.”" },
      { title: "Food and medicine", body: "Religious knowledge is taken on trust from the prophets, by learning God's Book and His messenger's practice and understanding them. By it the heart is made whole and kept from its diseases. Rational knowledge is not enough for the heart's health, though the heart needs it. Reason alone is not enough to keep the body healthy either. A person must learn from doctors what medicines do, because reason alone cannot find it. But once he hears it, he cannot understand it without reason. So reason cannot do without hearing, and hearing cannot do without reason. Whoever calls for pure trust and sets reason wholly aside is ignorant. Whoever relies on reason alone, without the lights of the Quran and the practice, is deceived. Be neither: join the two. Rational knowledge is like food and religious knowledge like medicine. A sick person is harmed by food when he misses his medicine. The heart's diseases are cured only by the medicines of the law: the acts of worship the prophets arranged to heal hearts." },
      { title: "The blind man in the house", body: "Some think rational and religious knowledge contradict each other and cannot be joined. That thought, Ghazali says, comes from blindness in the eye of insight. Such a person may even find some religious teachings contradict others. Unable to join them, he thinks religion contradicts itself, grows confused and slips out of religion like a hair drawn out of dough. His own weakness made him imagine a fault in religion. He is like a blind man who went into a house and tripped over the pots. He said: “Why are these pots left in the way? Why aren't they put back?” They said: “The pots are in their places. You cannot find the way because you are blind. The strange thing is that you blame your stumbling on others, not on your blindness.”" },
      { title: "This world and the next", body: "Rational knowledge divides again into worldly and otherworldly. Worldly knowledge is medicine, arithmetic, geometry, astronomy and all the crafts and trades. Otherworldly knowledge is knowledge of the heart's states, the flaws in deeds, and God, His attributes and acts. The two usually push each other out. Whoever gives himself to one until he goes deep in it usually falls short in the other. Ali gave three pictures of this world and the next. They are like the two pans of a scale, like east and west, and like two wives of one man: please one and you anger the other." },
      { title: "Clever here, simple there", body: "So you see people who are clever in worldly matters, in medicine, arithmetic, geometry and philosophy, and ignorant about the next world. And you see people clever in the fine points of the next world who are ignorant of most worldly knowledge. The power of reason is usually not enough for both. So the Prophet said: “Most of the people of the Garden are the simple” — simple, that is, in worldly matters. Al-Hasan said in a sermon: “We knew people who, had you seen them, you would have called mad. Had they seen you, they would have called you devils.” So if you hear something strange about religion that clever people deny, do not let their denial put you off. Someone walking east cannot find what lies in the west." },
      { title: "Only the prophets hold both", body: "The Quran speaks of those “who do not hope to meet Us and are content with the life of this world and rest in it”. And of those who “know the outside of the life of this world, but are heedless of the next”. And: “Turn away from whoever turns from Our reminder and wants only the life of this world. That is the limit of their knowledge.” Full insight into the good of both this world and religion is hardly granted to anyone. It is granted to those God made firm to guide His servants in this life and the next. These are the prophets, supported by the Holy Spirit. They draw on a divine power wide enough for everything. Other hearts, when they give themselves to this world, turn from the next and fall short of perfection there." },
    ],
    closer: [
      { title: "Why food can harm", body: "The food-and-medicine picture explains why clever reasoning can make a sick heart worse. Food is good, but to a sick body without its medicine it is harmful. So reason is good, but a heart that refuses the medicine of worship is harmed by the very thing that should feed it." },
      { title: "The pots are in their places", body: "The blind man's story is aimed at a particular mistake: blaming religion for a contradiction that is really in the reader. Ghazali does not say the reader must stop thinking. He says the reader should suspect his own sight before he suspects the house." },
    ],
    distinction: ["Two errors about reason", "Pure trust", "Setting reason aside altogether — ignorance.", "Reason alone", "Setting aside the light of the Quran and the practice — deception."],
    misreading: "Do not read “most of the people of the Garden are the simple” as praise of ignorance. Ghazali means simple in worldly matters, and in the next section he puts the people of understanding at the highest levels.",
    reflection: "Think of a time you felt religion contradicted itself. Ask, as Ghazali would, whether the pots were really in the way.",
    audit: ["Do I take my medicine as well as my food?", "Do I blame religion for my own stumbling?", "Which world is my cleverness spent on?", "Do I let clever people's denial decide for me?"],
    nodes: ["knowledge", "intellect"],
    model: pair("Food and medicine", "Reason and revelation, as Ghazali pictures them.", [["Rational knowledge", "Like food: needed, but it harms a sick body that misses its medicine.", "balance"], ["Religious knowledge", "Like medicine: it heals the heart, and only reason can understand it.", "support"]]),
  }),
  makeChapter({
    id: 9, shortTitle: "Inspiration and learning", formalTitle: "The difference between inspiration and learning, and between the Sufis' way and the way of the thinkers",
    overview: "Knowledge that is not obvious reaches the heart in two ways. It may rush in as if thrown there, or it may be earned by reasoning. Ghazali separates learning, inspiration and revelation, then describes the Sufi way of polishing the heart and waiting, and the thinkers' reasons for preferring study.",
    thesis: "Inspiration and learning are the same knowledge, in the same place, from the same source. They differ only in how the veil is lifted, which in inspiration is not up to the person. Revelation differs from inspiration only in that the prophet sees the angel who brings it.",
    moves: [
      { title: "Three ways of arriving", body: "Knowledge that is not obvious comes into the heart in different ways. Sometimes it rushes in, as if thrown into the heart from where it does not know. Sometimes it is earned by reasoning and learning. What comes without earning is called inspiration. What comes by reasoning is called reflection and insight. What comes without effort divides again. In one kind, the person does not know how or from where it came. That is called inspiration, a breath into the heart. In the other, he sees the cause: the angel who throws it into the heart. That is called revelation, and it belongs only to prophets. Inspiration belongs to the friends of God and the pure. Earned knowledge belongs to scholars." },
      { title: "Two mirrors facing", body: "The heart is ready for the truth of all things to shine in it. It is kept from them only by the five causes. They are like a curtain hanging between the mirror of the heart and the Preserved Tablet. On that Tablet is written all that God has decreed until the Day of Resurrection. Truths shining from the Tablet into the heart are like a picture passing from one mirror into another facing it. The curtain between them is sometimes pulled aside by a hand. Sometimes a wind blows and moves it. So the winds of God's kindness may blow, and the veils lift from the eyes of the heart. Then some of what is written on the Tablet shines in it." },
      { title: "Sleep, death and waking", body: "This happens at times in sleep, and a person learns what is going to happen. The veil lifts completely at death, when the covering is removed. And it can lift while awake, by a hidden kindness from God. Then something rare of knowledge flashes into hearts from behind the curtain of the unseen. Sometimes it is like a sudden lightning flash. Sometimes it comes in a series, up to a point. Its lasting is extremely rare." },
      { title: "How they really differ", body: "Inspiration does not differ from earned knowledge in the knowledge itself, or in its place, or in its cause. It differs in how the veil is removed, which in inspiration is not by the person's choice. Revelation does not differ from inspiration in any of these either, only in seeing the angel who brings the knowledge. All knowledge reaches our hearts by means of angels. God says: “It is not for any human that God should speak to him except by revelation, or from behind a veil, or by sending a messenger who reveals by His permission what He wills.”" },
      { title: "The Sufi way", body: "The Sufis lean to inspired knowledge rather than taught knowledge. So they were not keen to study, to master what authors had written, or to examine arguments and proofs. They said the way is to put effort first. Wipe out the blameworthy traits, cut every tie, and turn to God with all your concern. Once that is done, God takes charge of His servant's heart and lights it with knowledge. When God takes charge of the heart, mercy pours over it. Light dawns in it, the chest opens, and the secret of the unseen kingdom is uncovered. The veil of heedlessness clears from the heart's face by the kindness of mercy, and divine truths shine in it. The person's only part is to get ready: pure cleaning, a gathered concern, true desire, complete thirst, and constant watching for what God opens." },
      { title: "Sitting alone with one word", body: "The prophets and friends of God, they say, had things unveiled and light poured into their chests not by learning, study or writing books. It came by doing without the world, freeing the heart from its busyness, and turning wholly to God. “Whoever is for God, God is for him.” So first cut the world's ties completely. Cut your concern for family, wealth, children, homeland, learning, office and status, until having and not having are the same to you. Then be alone in a corner, keeping only the obligatory and regular prayers. Sit with an empty heart and a gathered concern. Do not scatter your thought with reciting the Quran, studying commentary, books of hadith or anything else. Try to let nothing come to mind except God." },
      { title: "From the tongue to the meaning", body: "He keeps saying with his tongue, “God, God,” with his heart present. At last he reaches a state where he stops moving his tongue, and it is as if the word runs on it by itself. He stays with this until its trace leaves the tongue, and he finds his heart keeping up the remembrance. He keeps on until the sound, letters and shape of the word are wiped from his heart. The meaning alone stays in his heart, present and clinging to it as if it never leaves. He has a choice up to this point, and a choice in keeping the state by pushing away whisperings. He has no choice in bringing down God's mercy. By what he has done, he has only put himself in the way of the breezes of mercy. What is left is to wait for what God opens, as He opened it for prophets and friends of God this way." },
      { title: "Flashes, then more", body: "Suppose his desire is true, his concern pure and his keeping-up good. His desires do not pull at him, and the self's chatter about worldly ties does not distract him. Then flashes of truth shine in his heart. At first they are like lightning that does not stay. Then it returns, perhaps after a delay. When it returns it may stay, or it may be snatched away. If it stays, it may last long or not. Others like it may follow one after another, or it may keep to one kind. The levels of God's friends in this have no number, just as their natures and characters have no number. The whole way comes down to cleaning, clearing and polishing on your side, then readiness and waiting." },
      { title: "What the thinkers say", body: "The thinkers and people of reasoning did not deny this way, or that it can lead to this goal now and then. It is how most prophets and friends of God reached it. But they found the road hard, its fruit slow, and its conditions hard to gather. Wiping out every tie to that degree is almost impossible, they said. If it happens for a while, keeping it is harder still, since the least whisper or passing thought troubles the heart. The Prophet said: “The believer's heart turns over more than a pot at full boil.” During this struggle the body's balance may be upset, the mind confused and the body made ill. If the self has not first been trained and taught the truths of knowledge, false fancies catch in the heart. The self may rest in them for years, and life may end before success. How many Sufis took this road and stayed in one fancy for twenty years! Had they mastered knowledge first, the confusion in that fancy would have opened to them at once." },
    ],
    closer: [
      { title: "The treasure and the plough", body: "So study, the thinkers said, is surer and nearer to the goal. Leaving it is like someone who stops learning law because the Prophet never studied law but knew it by revelation, and hopes training will bring him there too. Such a person wrongs himself and wastes his life. He is like someone who gives up earning and ploughing in the hope of stumbling on a buried treasure. It is possible, but very unlikely." },
      { title: "First what the scholars have", body: "So, they said, first gain what the scholars have gained and understand what they said. After that there is no harm in waiting for what has not been unveiled to other scholars. Perhaps it will be unveiled after that through effort. Ghazali sets down both ways side by side, and neither is thrown out." },
    ],
    distinction: ["Two ways of knowing that are not taught", "Inspiration", "Thrown into the heart from where the person does not know.", "Revelation", "The same, but the prophet sees the angel who brings it."],
    misreading: "Do not read the Sufi way as permission to skip study. The thinkers' warning — twenty years lost in one fancy — is set down beside it, and their advice is to learn first, then wait.",
    reflection: "Notice the next time an understanding comes to you all at once, without your working it out. Ask what you had done to clear the way for it.",
    audit: ["Is my heart ready for anything to be thrown into it?", "Have I learned what the scholars learned?", "Am I stuck in a fancy I have never tested?", "What am I waiting for, and how?"],
    nodes: ["inspiration", "knowledge", "remember"],
    model: chain("The Sufi way, step by step", "As Ghazali records it.", [["Cut the ties", "Family, wealth, status — until having and not having are the same.", "balance"], ["Sit alone", "Only the obligatory and regular prayers; nothing else in mind.", "balance"], ["God, God", "On the tongue, then the heart, then the meaning alone.", "support"], ["Wait", "Flashes may come, and may stay; the opening is not in your hands.", "support"]]),
  }),
  makeChapter({
    id: 10, shortTitle: "The pool and the two doors", formalTitle: "The first picture of the difference: the pool filled from above or from below",
    overview: "The heart is outside the senses, so Ghazali explains it with pictures. The first is a pool that can be filled by streams from outside or by springs from deep below. It leads him to the four levels at which the world exists. It also leads to the heart's two doors, one open to the senses and one open to the unseen kingdom.",
    thesis: "The heart has two doors. One opens onto the visible world through the five senses. The other opens inward onto the unseen kingdom and the Preserved Tablet. The knowledge of scholars comes in by the first; the knowledge of prophets and friends of God wells up through the second.",
    moves: [
      { title: "Streams or springs", body: "Picture a pool dug in the ground. Water could be brought to it from above, by opening streams into it. Or you could dig in the bottom of the pool and lift out the earth, until you come near the clear water beneath. Then water bursts up from the bottom. That water is clearer and lasts longer, and may be more plentiful. The heart is the pool, and knowledge is the water. The five senses are the streams. Knowledge can be brought into the heart through the streams of the senses and reflection on what is seen, until it is full. Or the streams can be blocked by solitude, withdrawal and lowering the gaze. Then a person works on the depth of the heart, cleaning it and lifting its layers of veils, until springs of knowledge burst out from within." },
      { title: "How can an empty heart overflow?", body: "You may ask how knowledge can burst out of the heart itself, when it is empty of it. Ghazali says this is one of the heart's wonderful secrets, and cannot be fully told in a book on practice. What can be said is this. The truths of things are written in the Preserved Tablet, and in the hearts of the angels brought near. An architect draws the plan of a house on paper, then builds it to match the plan. In the same way, the Maker of the heavens and the earth wrote the plan of the world, from its beginning to its end, on the Preserved Tablet. Then He brought it into being to match that plan." },
      { title: "Four levels of existence", body: "From the world that exists, another form passes into the senses and the imagination. Whoever looks at the sky and the earth and then shuts his eyes sees them in his imagination, as if still looking. If the sky and earth ceased to exist and he remained, he would find their form in himself. Then a trace passes from his imagination to his heart, and the truths of things that entered his senses settle there. So the world has four levels of existence. It exists on the Preserved Tablet, before it exists in bodies. Then it exists in reality. Then it exists in imagination. Then it exists in the mind, as its form in the heart. Some of these levels are spiritual and some bodily, and some of the spiritual are more spiritual than others." },
      { title: "The world in the pupil", body: "This is a kindness of divine wisdom. God made the pupil of your eye so small, and yet the whole wide world, heavens and earth, prints itself on it. From its existence in the senses comes an existence in the imagination, and from that an existence in the heart. You can only perceive what reaches you. If God had not put a likeness of the whole world in your own self, you would know nothing of what lies outside you. Glory to the One who arranged these wonders in hearts and eyes, then made hearts and eyes blind to them. Most people's hearts are ignorant of themselves and their wonders." },
      { title: "The sun and its reflection", body: "So the truth and form of the world can reach the heart from the senses at one time and from the Preserved Tablet at another. In the same way, the sun's image can reach the eye by looking at the sun, or by looking at water that reflects it. When the veil between the heart and the Tablet lifts, the heart sees things there. Knowledge bursts into it from there, and it no longer needs to borrow from the senses. That is like water bursting up from deep in the ground. When the heart turns to the images gathered from the senses, they become a veil between it and the Tablet. Water collected in streams stops the springs bursting up. And whoever looks at the sun's reflection in water is not looking at the sun itself." },
      { title: "Two doors", body: "So the heart has two doors. One opens onto the unseen kingdom: the Preserved Tablet and the world of angels. The other opens onto the five senses, which hold on to the visible world. The visible world also copies the unseen one in some way. The door to the senses needs no explaining. The inner door you can know with certainty by thinking about true dreams. In sleep the heart sees what will happen or what has happened, without borrowing anything from the senses." },
      { title: "The solitary ones", body: "That inner door opens only for someone given over to the remembrance of God. The Prophet said: “The solitary ones have gone ahead.” He was asked who they are. He said: “Those devoted to the remembrance of God. Remembrance has lifted their burdens from them, and they arrive at the Resurrection light.” Then he described them, reporting God's words: “Then I turn My face towards them. Do you think anyone knows what I mean to give the one I face? The first thing I give them is that I throw light into their hearts. Then they tell of Me, as I tell of them.” The way in for such knowledge is the inner door." },
    ],
    closer: [
      { title: "Scholars and saints", body: "So the difference between the knowledge of prophets and friends of God and the knowledge of scholars and sages is this. Theirs comes from within the heart, through the door open to the unseen kingdom. Wisdom comes in through the doors of the senses, open to the visible world." },
      { title: "Where the book stops", body: "The heart's going back and forth between the visible and the unseen worlds cannot be fully explained in a book on practice, Ghazali says. The pool is a picture meant to show the two ways in. The second picture, next, shows the two kinds of work." },
    ],
    distinction: ["Two ways to fill the pool", "Streams from outside", "Knowledge brought in through the senses and reflection — the scholars' way.", "Springs from below", "Knowledge welling up when the veils are lifted — the way of prophets and friends of God."],
    misreading: "Do not read the springs as knowledge that comes from nowhere. Ghazali says it comes from the Preserved Tablet and the angels, through a door that true dreams prove exists.",
    reflection: "Think of a true dream you, or someone you trust, has had. Ghazali takes it as proof that the heart has an inner door.",
    audit: ["Which door is my heart mostly open by?", "Do the streams of my senses ever fall quiet?", "Do I look at the sun, or at its reflection?", "Is remembrance lifting any burden from me?"],
    nodes: ["unseen", "knowledge", "senses"],
    model: chain("Four levels of the world", "Each level copies the one before it.", [["On the Tablet", "The plan, written before anything exists.", "support"], ["In reality", "The world brought into being to match it.", "support"], ["In imagination", "Its image, kept when the eyes shut.", "balance"], ["In the heart", "Its truth, understood.", "support"]]),
  }),
  makeChapter({
    id: 11, shortTitle: "The Chinese and Byzantine painters", formalTitle: "The second picture: the painters and the polishers, and how lights differ on the Day",
    overview: "Ghazali's second picture shows the two kinds of work. Painters from China and from Byzantium competed before a king. One side painted; the other only polished. Then he turns to what knowledge is worth after death. Lights differ in size on the Bridge, and levels in the Garden are as far apart as the rich and the richer.",
    thesis: "Scholars work to bring knowledge into the heart, like painters. Friends of God work only to polish the heart until the truth shines in it, like polishers. Whatever the way, a person's happiness is only by knowledge, and people's levels in the next world follow their levels of knowing.",
    moves: [
      { title: "The contest", body: "It is told that the people of China and the people of Byzantium boasted before a king about their skill in painting and design. The king decided to give them a hall. The Chinese would paint one side and the Byzantines the other, with a curtain hung between them so neither could see the other's work. It was done. The Byzantines gathered more rare paints than could be counted. The Chinese went in with no paint at all, and set about polishing their side and making it shine." },
      { title: "Lifting the curtain", body: "When the Byzantines finished, the Chinese said they had finished too. The king was amazed. How could they finish painting without paint? They said: “Never mind. Lift the curtain.” They lifted it, and there on the Chinese side shone all the wonders of the Byzantine art, with extra brightness and gleam. Their side had become like a polished mirror from so much polishing. Its beauty grew with the polishing." },
      { title: "Who the polishers are", body: "So it is with the care of God's friends for cleaning, polishing, purifying and clearing the heart, until the truth shines in it with the greatest brightness. That is what the Chinese did. The care of sages and scholars is for earning, painting knowledge and getting it painted on the heart. That is what the Byzantines did. Either way, the believer's heart does not die. Its knowledge is not wiped out at death, and its clearness is not clouded. Al-Hasan pointed to this: “The earth does not eat the place where faith lives.” It becomes a means of drawing near to God." },
      { title: "No happiness without knowledge", body: "As for knowledge actually gained, and the clearness and readiness to receive it, no one can do without them. There is no happiness for anyone except by knowledge and knowing God. Some happiness is nobler than other happiness, just as there is no wealth except by money. The owner of one coin is rich in a way, and the owner of full treasuries is rich. The happy differ in level as their knowing and faith differ, just as the rich differ as their money is more or less." },
      { title: "Lights on the Bridge", body: "Knowledge is light, and believers go to meet God only by their lights. “Their light runs ahead of them and on their right.” A report says some are given a light as big as a mountain, and some less. The last of them is a man given a light on his big toe. It shines at one moment and goes out at another. When it shines, he puts his foot forward and walks. When it goes out, he stands still. They cross the Bridge according to their light. Some cross in the blink of an eye, some like lightning, some like a cloud, some like a falling star, some like a horse at full gallop. The one with a light on his toe crawls on his face, hands and feet. He drags one hand and holds up another, and the Fire catches at his sides. He keeps on like that until he gets through." },
      { title: "The sun and the lamps", body: "This shows how people differ in faith. If Abu Bakr's faith were weighed against the faith of all the world, apart from the prophets and messengers, it would outweigh it. That is like saying: if the sun's light were weighed against all the lamps, it would outweigh them. The light of one ordinary person is like a lamp. Some have the light of a candle. The faith of the truthful is like the light of the moon and stars. The faith of the prophets is like the sun. In sunlight the whole horizon shows in all its width. In lamplight only a narrow corner of a room shows. So the opening of the chest and the unveiling of the unseen kingdom differ in the hearts of those who know." },
      { title: "An atom's weight", body: "So a report says what will be said on the Day of Resurrection. “Bring out of the Fire whoever has in his heart the weight of a mithqal of faith.” Then it says half a mithqal, a quarter, a grain of barley, an atom. All this points to the difference in levels of faith. Such small amounts of faith do not stop a person entering the Fire. It follows that whoever has more than a mithqal does not enter it, for if he did, the order to bring him out would have come first. And whoever has an atom's weight will not stay in the Fire forever, even if he enters it. The Prophet said: “Nothing is better than a thousand of its kind, except the believing human being.” He meant the heart of one who knows God with certainty. It is better than a thousand hearts of ordinary people." },
      { title: "Believers and knowers", body: "God says: “You are the highest, if you are believers.” This, Ghazali says, raises believers above those who merely submit, and means the believer who knows, not the one who only follows. God says: “God raises those of you who believe, and those given knowledge, by levels.” Here those who believe are those who accepted without knowledge, set apart from those given knowledge. This shows the name believer applies to one who follows on trust, even without insight. Ibn Abbas explained the verse: “God raises the scholar above the believer by seven hundred levels. Between each two levels is the distance between heaven and earth.” The Prophet said: “Most of the people of the Garden are the simple, and the highest places are for the people of understanding.” And: “The scholar's excellence over the worshipper is like my excellence over the least of my Companions.” In another version: “like the full moon over all the other stars.”" },
    ],
    closer: [
      { title: "The Day of Mutual Loss", body: "So the Day of Resurrection is the Day of Mutual Loss. Whoever is kept from God's mercy suffers a huge loss. And even the one who is not kept from it sees great levels above his own. He looks at them the way a man with ten coins looks at a man who owns the earth from east to west. Both are rich, but how great the difference! How great the loss of the one who lets his share slip! “The next world is greater in levels and greater in excellence.”" },
      { title: "Both painters win", body: "The king's hall ends with both sides beautiful. Ghazali does not make the Byzantines lose. What the Chinese show is that polishing lets the whole wall take in what is painted opposite, with light of its own." },
    ],
    distinction: ["Two kinds of work", "The painters", "Scholars and sages, bringing knowledge into the heart by earning it.", "The polishers", "Friends of God, only clearing the heart until the truth shines in it."],
    misreading: "Do not read the polishers as people who know nothing. The Chinese wall showed every picture on the other side, and brighter. Ghazali says no one reaches happiness except by knowledge.",
    reflection: "Ask what your light would be on the Bridge — a mountain, a candle, or a light on one toe — and what would make it larger.",
    audit: ["Am I painting, polishing, or neither?", "How large would my light be?", "What level am I content with?", "What share am I letting slip?"],
    nodes: ["mirror", "knowledge", "unseen"],
    model: chain("Lights on the Bridge", "Crossing at the speed of one's light.", [["A light like a mountain", "Across in the blink of an eye, or like lightning.", "support"], ["Smaller lights", "Like a cloud, a falling star, a galloping horse.", "support"], ["A light on the toe", "Walks when it shines, stops when it fades.", "balance"], ["Crawling through", "Dragging a hand, touched by the Fire — until he gets through.", "warning"]]),
  }),
  makeChapter({
    id: 12, shortTitle: "Proofs of the inner door", formalTitle: "Evidence from the revealed law, from experience, and from reason that knowledge can come without learning",
    overview: "Whoever has had even a little knowledge come to him by inspiration knows the Sufi way is real. Whoever has not should still believe in it. Ghazali gathers the evidence: verses and reports, and stories of the Companions and later saints. Then come two proofs no one can deny: true dreams, and the Prophet's news of the unseen.",
    thesis: "The revealed law, experience and reason all show that the heart has a door onto the unseen, opened by striving, mindfulness of God and turning from worldly desires. Whoever believes in prophets and true dreams must accept that knowledge is not limited to learning.",
    moves: [
      { title: "From the Quran", body: "“Those who strive for Us, We will surely guide them to Our paths.” Every wisdom that appears from the heart through steady worship, without learning, comes by unveiling and inspiration. The Prophet said: “Whoever acts on what he knows, God gives him knowledge of what he did not know.” God says: “Whoever is mindful of God, He makes a way out for him, and provides for him from where he does not expect.” The way out is from confusions and doubts. That is, He teaches him without learning and gives him understanding without experience. “If you are mindful of God, He will give you a criterion.” It was explained as a light to tell truth from falsehood and escape doubts." },
      { title: "A prayer for light", body: "So the Prophet often asked for light in his prayers. He said: “God, give me light, and increase me in light. Put light in my heart, light in my grave, light in my hearing and light in my sight.” He went on until he said: “in my hair, in my skin, in my flesh, my blood and my bones.” He prayed for Ibn Abbas: “God, give him understanding in religion and teach him interpretation.” Ali said: “We have nothing the Prophet told us in secret, except that God gives a servant understanding of His Book.” That is not by learning. It was said of the verse “He gives wisdom to whom He wills” that it means understanding of God's Book. And God says: “We made Solomon understand it,” giving what was unveiled the name of understanding." },
      { title: "The believer's insight", body: "Abu al-Darda used to say: “The believer looks by God's light, from behind a thin veil. By God, it is the truth: God throws it into their hearts and runs it on their tongues.” One of the early Muslims said: “The believer's hunch is a kind of seeing.” The Prophet said: “Beware the insight of the believer, for he looks by the light of God.” A scholar was asked what inner knowledge is. He said: “A secret of God's secrets. He throws it into the hearts of those He loves, and shows it to no angel or human.” The Prophet said: “Among my community are some who are spoken to, taught and addressed, and Umar is one of them.” Ibn Abbas used to read a verse as: “We sent before you no messenger, no prophet and no one spoken to” — meaning the truthful. The one spoken to is the inspired, to whom things are unveiled from inside his heart, not from outside." },
      { title: "Knowledge from His presence", body: "The Quran states that mindfulness is the key to guidance and unveiling, and that is knowledge without learning. “In what God created in the heavens and the earth are signs for people who are mindful” — it makes them theirs. Abu Yazid and others used to say: “The scholar is not the one who memorises from a book, so that when he forgets he is ignorant. The scholar is the one who takes his knowledge from his Lord whenever he wishes, without memorising or study.” That is lordly knowledge, which God points to in: “We taught him knowledge from Our presence.” All knowledge is from God's presence. But some comes through creatures teaching. The knowledge called “from His presence” opens in the heart's secret with no familiar outside cause. If all the verses, reports and sayings on this were gathered, they could not be counted." },
      { title: "The Companions saw it", body: "As for experience, it too is past counting, and it appeared among the Companions, their followers and those after. Abu Bakr said to Aisha when he was dying: “They are only your two brothers and your two sisters.” His wife was pregnant, and she gave birth to a girl. He had known before the birth that it was a girl. Umar, in the middle of a sermon, called out: “Sariya! The mountain, the mountain!” It had been unveiled to him that the enemy was bearing down on Sariya's army, and he warned him. His voice then reaching Sariya was among the great wonders." },
      { title: "Uthman and the look", body: "Anas ibn Malik said: “I went in to see Uthman. On the way I had met a woman, and I had looked sideways at her and dwelt on her beauty. When I came in, Uthman said: one of you comes in to me with the trace of unlawful looking plain in his eyes! Aren't you aware that the eyes commit adultery by looking? You will repent, or I will punish you. I said: is there revelation after the Prophet? He said: no, but insight, proof and true discernment.”" },
      { title: "The saints' stories", body: "Abu Sa'id al-Kharraz said: “I went into the Sacred Mosque and saw a poor man in two rags. I said to myself: he and his like are a burden on people. He called to me: God knows what is in your selves, so beware of Him. I asked God's forgiveness silently. He called to me: He is the one who accepts repentance from His servants. Then he vanished.” Abu al-Abbas ibn Masruq visited Abu al-Fadl al-Hashimi, who was ill and had a family and no known income. As he stood to leave, he thought: where does this man get his food? Abu al-Fadl cried out: “Abu al-Abbas, put away that mean thought. God has hidden kindnesses.”" },
      { title: "Al-Shibli's fifty dinars", body: "Ahmad al-Naqib went in to al-Shibli, who said: “I am being tested, Ahmad. A thought came to me that I am mean. I said I am not. The thought came back: yes, you are. So I resolved: whatever comes to me today, I will give to the first poor man I meet.” Before the thought was finished, a servant of Mu'nis the eunuch came in with fifty dinars for his needs. He went out and found a blind poor man having his head shaved by a barber. He held out the dinars. The man said: “Give them to the barber.” Al-Shibli said: “It is such-and-such a sum.” The man said: “Didn't we tell you that you are mean?” He gave them to the barber, who said: “When this poor man sat down, we agreed to take no fee from him.” So al-Shibli threw the money into the Tigris, saying: “No one honours you without God humbling him.”" },
      { title: "Abu al-Khayr and the lion", body: "Hamza ibn Abd Allah al-Alawi visited Abu al-Khayr al-Tinati. He resolved in himself to greet him but not eat in his house. As he left, Abu al-Khayr caught up with him carrying a tray of food. “Eat, young man. You are now out of your resolution.” Ibrahim al-Raqqi went to greet him. At the sunset prayer, Abu al-Khayr could hardly recite the Opening chapter correctly. Ibrahim thought: my journey is wasted. After the prayer he went out to wash, and a lion came at him. He ran back and said a lion had come at him. Abu al-Khayr went out and shouted at it: “Didn't I tell you not to bother my guests?” The lion moved off. Then he said to Ibrahim: “You busied yourselves with setting the outside straight, so you feared the lion. We busied ourselves with setting the inside straight, so the lion fears us.”" },
    ],
    closer: [
      { title: "Two proofs no one can deny", body: "Stories do not help someone who denies, until he sees it in himself. But two proofs cannot be denied. One is true dreams, which uncover the unseen. If that is possible asleep, it is not impossible awake. Sleep differs from waking only in the senses resting. How many waking people are so sunk in themselves that they neither hear nor see! The other is the Prophet's news of the unseen and of the future, as in the Quran. If it is possible for the Prophet, it is possible for others. A prophet is someone shown the truths of things and set to put people right. It is not impossible for someone to be shown the truths without being set to put people right. He is called not a prophet but a friend of God. So whoever believes in prophets and true dreams must accept that the heart has two doors." },
      { title: "The angels who do not see", body: "One who was shown things said: “The two recording angels appeared to me. They asked me to dictate some of my hidden remembrance of God's oneness. They said: we write no deed of yours from it, and we want to carry up a deed for you to bring you near to God.” He said to them: “Don't you write the obligatory acts?” They said yes. He said: “That is enough for you.” This shows the noble scribes see only outward deeds, not the heart's secrets. Another asked one of the Abdal a question about certainty. He turned left and asked: “What do you say?” Then right. Then he bowed his head to his chest and asked. Then he gave the strangest answer. He explained. The one on the left did not know. The one on the right, who knows more, did not know either. So he asked his heart, which knew more than both. God says in a report: “When I look into a slave's heart and find My remembrance ruling it, I take charge of his affairs. I become his companion and his friend.” Abu Sulayman al-Darani said the heart is like a dome with closed doors around it; whichever door opens works in it. Umar wrote to his generals: “Keep what you hear from the obedient, for true things are made clear to them.”" },
    ],
    distinction: ["Two kinds of proof", "Stories", "Past counting — but no use to a denier until he tastes it himself.", "Dreams and prophecy", "Undeniable: if the unseen can open to a sleeper or a prophet, the door exists."],
    misreading: "Do not read these stories as tricks to impress. Each one is about the heart: Uthman's insight into a look, al-Shibli caught by his own thought, and the lion that fears those who straighten their insides.",
    reflection: "Think of a time someone saw something in you that you had not said. Ghazali would ask what they had been doing with their own heart.",
    audit: ["Have I ever tasted knowledge I did not learn?", "Is my inside as straight as my outside?", "Do I act on what I know?", "What thought would a man of insight catch in me?"],
    nodes: ["inspiration", "unseen", "remember"],
    model: set("Three kinds of evidence", "How Ghazali supports the inner door.", [["The law", "Verses and reports: striving, mindfulness, light, understanding.", "support"], ["Experience", "Abu Bakr, Umar, Uthman, al-Shibli, Abu al-Khayr.", "support"], ["Reason", "True dreams and the Prophet's news of the unseen.", "support"]]),
  }),
  makeChapter({
    id: 13, shortTitle: "The angel's touch, the devil's touch", formalTitle: "Satan's hold on the heart through whispering: what whispering is, and why it wins",
    overview: "The heart is struck by thoughts from every side. Ghazali traces how an act begins as a passing thought. He argues that different thoughts need different causes. The cause of a good thought is called an angel, and the cause of a bad one a devil. The heart is a battlefield between them, and most hearts have already been taken.",
    thesis: "Every act begins as a passing thought. A thought that calls to good is inspiration, and its cause is an angel. A thought that calls to evil is whispering, and its cause is a devil. The heart is equally fit for both. Which one settles in it depends on whether it follows desire or resists it.",
    moves: [
      { title: "A dome with doors", body: "The heart is like a dome with doors, and states pour into it through every door. It is also like a target, with arrows flying at it from all sides. Or a mirror set up where all kinds of images pass, one after another, so that it is never empty. Or a pool, fed by different waters from streams opening into it. From outside, things come in through the five senses. From inside, they come through imagination, desire, anger and the traits built into a person's nature. Whatever the senses take in leaves a trace on the heart. When desire stirs, from overeating or a strong constitution, that leaves a trace too. Even with the senses shut, images stay in the mind and move from one thing to another. The heart moves from state to state as they move. So the heart is always being changed." },
      { title: "From a thought to the limbs", body: "The most particular traces in the heart are passing thoughts (khawatir). By these Ghazali means ideas and memories that come to it, new or recalled. They are called passing thoughts because they pass into the heart after it was unaware of them. Passing thoughts are what move the will. Intention, resolve and will can only come after the thing intended has crossed the mind. So acts begin with a passing thought. The thought stirs a wish. The wish stirs resolve. Resolve stirs intention. Intention moves the limbs." },
      { title: "Smoke and light", body: "Some thoughts call to evil, meaning what does harm in the end. Some call to good, meaning what helps in the next world. The praiseworthy thought is called inspiration. The blameworthy one, calling to evil, is called whispering. These thoughts come into being, and whatever comes into being has a cause. When effects differ, their causes differ; that is God's way of ordering causes. Picture the walls of a house lit by a fire, and its ceiling blackened by smoke. You can tell the cause of the black is not the cause of the light. So the heart's light and its darkness have two different causes. The cause of a thought calling to good is called an angel. The cause of a thought calling to evil is called a devil." },
      { title: "Pairs", body: "The grace by which the heart is made ready to accept good inspiration is called being granted success (tawfiq). What makes it ready to accept the devil's whisper is called being led astray and forsaken. An angel is a creature God made to pour out good, give knowledge, uncover the truth, promise good and command what is right. A devil is a creature made for the opposite: promising evil, commanding indecency, and threatening poverty whenever a person means to do good. So whispering faces inspiration, the devil faces the angel, and success faces being forsaken. God says: “Of everything We created pairs.” All created things come in opposing pairs. Only God has no opposite; He is the One who created all the pairs." },
      { title: "Two touches", body: "So the heart is pulled between the devil and the angel. The Prophet said: “There are two touches in the heart. One is a touch from the angel: a promise of good and a confirming of the truth. Whoever finds it should know it is from God, and praise Him. The other is a touch from the enemy: a promise of evil, a denying of the truth, and a forbidding of good. Whoever finds it should seek refuge in God from the cursed devil.” Then he recited: “The devil promises you poverty and commands you to indecency.” Al-Hasan said: “They are two concerns that roam the heart: one from God, one from the enemy. God have mercy on the one who stops at his concern. What is from God, he goes ahead with. What is from the enemy, he fights.”" },
      { title: "Between two fingers", body: "Because the heart is pulled between these two, the Prophet said: “The believer's heart is between two of the fingers of the Merciful.” God is far above having fingers of flesh, blood and nerve, divided into joints. The spirit of a finger is its speed in turning things over and its power to move and change them. You want your finger for what it does, not for itself. You do things with your fingers, and God does what He does by putting the angel and the devil to work. Both are made subject to His power in turning hearts, as your fingers are subject to you in turning things over." },
      { title: "Everyone has a devil", body: "By its nature the heart is equally fit to take in the angel's traces and the devil's. Neither side wins by itself. One side wins when a person follows desire and sinks into lusts, or turns from them and goes against them. If he follows anger and desire, the devil's rule shows, working through desire. The heart becomes the devil's nest, because desire is his pasture. If he fights his lusts and takes on the angels' manners, his heart becomes a place where angels land. No heart is free of desire, anger, greed, craving and long hopes. So no heart is free of the devil roaming in it. The Prophet said: “There is none of you but has a devil.” They said: “Even you, messenger of God?” He said: “Even me. But God helped me against him, and he submitted, so he only commands good.”" },
      { title: "The battlefield", body: "The devil works only through desire. If God helps someone with his desire until it goes only where and as far as it should, it calls to no evil. Then the devil wearing it as armour commands only good. When worldly thoughts driven by desire take over the heart, the devil finds room and whispers. When the heart turns to the remembrance of God, the devil moves off, his room shrinks, and the angel comes and inspires. The chasing back and forth between the armies of angels and devils in the heart's battlefield never stops, until the heart opens to one of them. That one settles in and takes hold, and the other only slips past. Most hearts have been taken and owned by the devils' armies. They are full of whispers urging this world over the next. It began with following lusts and desire. They can only be won back by emptying the heart of the devil's food, which is desire, and filling it with the remembrance of God." },
      { title: "Thieves and an empty house", body: "Jabir ibn Ubayda al-Adawi complained to al-Ala ibn Ziyad of the whispering he found in his chest. He said: “That is like a house thieves pass. If there is something in it, they try for it. If not, they move on.” A heart empty of desire, he meant, the devil does not enter. So God says to the devil: “Over My servants you have no authority.” Whoever follows desire is desire's slave, not God's, and God sets the devil over him. Uthman ibn Abi al-As told the Prophet: “The devil has come between me and my prayer and my reciting.” He said: “That is a devil called Khinzab. When you sense him, seek refuge in God from him and spit lightly three times to your left.” He did, and God took it from him. A report says: “Ablution has a devil called al-Walhan. Seek refuge in God from him.”" },
    ],
    closer: [
      { title: "Only remembrance is safe", body: "Nothing wipes the devil's whisper from the heart except remembering something other than what he whispers. When something new comes to mind, what was there before goes. But anything besides God, and what relates to Him, can itself become the devil's ground. Only the remembrance of God is safe from him. A thing is cured by its opposite. The opposite of all his whispers is to remember God, seeking refuge and disowning your own power: “I take refuge in God from the cursed devil. There is no power and no strength except by God, the High, the Great.” Mujahid explained “the whisperer who draws back”. He is spread over the heart. When God is remembered he draws back and shrinks, and when the person forgets, he spreads again. Anas reported the Prophet: “The devil has his snout on the heart of Adam's child. If he remembers God, it draws back. If he forgets God, it swallows his heart.”" },
      { title: "In the blood, on the road", body: "Just as desires are mixed into a person's flesh and blood, the devil's rule runs through his flesh and blood and surrounds his heart. The Prophet said: “The devil runs in a person like blood. Narrow his channels with hunger.” Hunger breaks desire, and desire is the devil's channel. So Iblis said: “I will come at them from in front and behind, from their right and their left.” The Prophet said the devil sat in wait on a person's paths. On the path of Islam he said: “Will you leave your religion and your fathers' religion?” He disobeyed him and became Muslim. On the path of emigration: “Will you leave your land and your sky?” He disobeyed him and emigrated. On the path of striving in God's cause: “You will be killed, your wives will remarry and your wealth will be shared out.” He disobeyed him and went. These thoughts, Ghazali says, are what the whispering is. Every person has them; people differ only in obeying or refusing." },
    ],
    distinction: ["Two touches in the heart", "The angel's", "A promise of good and a confirming of the truth — praise God for it.", "The devil's", "A promise of evil, a denying of the truth, a forbidding of good — seek refuge from it."],
    misreading: "Do not read the angel and the devil as only names for good and bad moods. Ghazali argues from the thoughts to their causes, as from smoke and light to fire, and names the causes as the reports name them.",
    reflection: "Next time a thought stops you from doing something good by warning you of loss, remember the verse Ghazali quotes: the devil promises you poverty.",
    audit: ["Which touch did I feel last?", "Is my heart the devil's pasture, or a place where angels land?", "Do I stop at my concerns, as al-Hasan asked?", "What is there in my house for the thieves?"],
    nodes: ["thought", "devil", "angel", "remember"],
    model: chain("How an act begins", "From the first passing thought to the limbs.", [["A passing thought", "An idea or memory crosses the heart.", "balance"], ["A wish", "The thought stirs a wanting.", "balance"], ["Resolve", "The wanting firms up.", "warning"], ["Intention", "The resolve takes aim.", "warning"], ["The limbs", "The body carries it out.", "warning"]]),
  }),
  makeChapter({
    id: 14, shortTitle: "Evil dressed as good", formalTitle: "Knowing the enemy by his weapons: the thoughts that are hard to sort, and the devil's hidden paths",
    overview: "Ghazali refuses to ask what the devil is made of; that is like studying the colour of a snake inside your clothes. What matters is his weapons. The hardest thoughts to sort are the ones where evil comes dressed as good. The devil has many doors into the heart, while the angels have one, and even a small first step can drag a person into ruin.",
    thesis: "Work to drive the enemy off, not to learn his pedigree. His weapons are desire and lust. His subtlest trick is to dress evil as good, and it ruins scholars and worshippers who would never touch open sin. So stop at every concern that comes to you, and judge it by the light of mindfulness and knowledge.",
    moves: [
      { title: "The snake in your clothes", body: "Once the meaning of whispering and inspiration, angel and devil, success and being forsaken is clear, some ask about the devil's nature. Is he a fine body, or not a body at all? If a body, how does he enter a person's body? A book on practice does not need this. Someone who asks it is like a man with a snake inside his clothes. He needs to get it out and stop it harming him. Instead he busies himself studying its colour, shape, length and width. That is ignorance itself. You have met the thoughts that urge evil. You know they have a cause. You can see that whatever urges an evil you will regret is an enemy. So you know the enemy. Get on with fighting him." },
      { title: "Ask about his weapons", body: "God has made the devil's enmity known in many places in His Book, so that people believe in it and guard against it. “The devil is an enemy to you, so take him as an enemy. He only calls his party to be among the people of the Blaze.” And: “Did I not charge you, children of Adam, not to serve the devil? He is a clear enemy to you.” So a person should busy himself with driving the enemy off, not with asking about his origin, family and home. He should ask about his weapons, to drive him away. The devil's weapons are desire and lust, and knowing that is enough. Knowing his nature, and the nature of the angels, is the field of those who go deep into unveiling. Practice does not need it." },
      { title: "Three kinds of thought", body: "Thoughts are of three kinds. Some are known for certain to call to evil; they are plainly whispering. Some are known to call to good; they are plainly inspiration. And some leave a person unsure whether they come from the angel's touch or the devil's. One of the devil's plots is to present evil as good. Telling the two apart is subtle, and most worshippers are ruined by it. The devil cannot call them to open evil, so he paints evil in the colours of good." },
      { title: "The preacher's ruin", body: "He says to a scholar, as if giving advice: “Don't you see people dead with ignorance, perishing in heedlessness, on the edge of the Fire? Have you no mercy for God's servants? Save them with your counsel. God has given you a seeing heart, a fluent tongue and a pleasing voice. How can you be ungrateful for God's gift, invite His anger, and keep quiet?” He keeps at it with gentle tricks until the scholar starts preaching. Then he calls him to dress up for his audience, polish his words and show off his goodness. “If you don't, your words won't reach their hearts.” All the while he strengthens in him the taint of showing off, love of being accepted, the pleasure of status and followers, and looking down on people. The poor man is led to ruin by way of good advice. He speaks thinking his aim is good, while his aim is status and acceptance. He thinks he stands high with God. The Prophet said: “God supports this religion with people who have no share in the next world.”" },
      { title: "A true word, not on his say", body: "It is told that Iblis appeared to Jesus son of Mary and said: “Say: there is no god but God.” Jesus said: “It is a true word, but I will not say it because you say so.” The devil has his tricks even under good. His tricks of this kind have no end. By them he ruins scholars, worshippers, ascetics, the poor and the rich. He ruins all kinds of people who dislike open evil and would never sink into plain sins. Ghazali says he will give many of the devil's plots in the Book of Self-Deception at the end of this quarter. If time allows, he may write a whole book on it, called The Devil's Deception. It has spread, he says, through lands and people, above all in schools and beliefs, until nothing of good is left but its outline." },
      { title: "Stop at every concern", body: "So it is a duty to stop at every concern that comes to mind, and learn whether it is the angel's touch or the devil's. Look at it hard with the eye of insight, not with the craving of your nature. Only the light of mindfulness, insight and deep knowledge can show it. “When those who are mindful are touched by a prowler from the devil, they remember, and at once they see.” They return to the light of knowledge, and the confusion is uncovered for them. Whoever has not trained himself in mindfulness leans by nature to accept the devil's tricks. His mistakes multiply, and he rushes to his ruin without knowing. Of such people God says: “There will appear to them from God what they never expected.” It was explained as deeds they thought were good, which turned out to be bad. The hardest part of the knowledge of practice is spotting the tricks of the self and the plots of the devil. It is a duty on every person, and people have neglected it." },
      { title: "A fight until death", body: "Only closing the doors of thoughts saves from much whispering. Their outer doors are the five senses. Their inner doors are the lusts and ties of this world. Being alone in a dark room closes the doors of the senses. Leaving family and wealth cuts down the inner ways in. Even then inner ways remain, in the images running through the heart. Only filling the heart with the remembrance of God drives those off. Then the devil keeps pulling at the heart, fighting it and distracting it from remembrance. So he must be fought, and this fight ends only with death. No one is free of the devil while he lives. He may grow strong enough not to obey him. But he never stops needing to fight while blood runs in his body. The doors stay open: desire, anger, envy, greed, gluttony and the rest. While a door is open and the enemy awake, only guarding and fighting keep him out. A man asked al-Hasan: “Does the devil sleep?” He smiled and said: “If he slept, we would get some rest.”" },
      { title: "The worn-out devil", body: "Still, a believer can push him back and weaken him. The Prophet said: “The believer wears out his devil as one of you wears out his camel on a journey.” Ibn Mas'ud said: “The believer's devil is thin.” Qays ibn al-Hajjaj said: “My devil told me: when I entered you I was like a fat slaughter-camel. Now I am like a sparrow. I asked why. He said: you melt me with the remembrance of God.” The mindful can close and guard the open doors, the plain roads to plain sins. They stumble on his hidden paths, which they do not find to guard, as with the self-deception of scholars and preachers. The trouble is that the devil's doors into the heart are many, while the angels' door is one. That one door is confused among the many. A person is like a traveller in a desert of many tracks on a dark night. Only a seeing eye and a rising sun show the way. The seeing eye is the heart cleared by mindfulness. The rising sun is deep knowledge from God's Book and His messenger's practice." },
      { title: "The lines in the sand", body: "Ibn Mas'ud said: “The messenger of God drew a line for us one day and said: this is God's path. Then he drew lines to its right and left and said: these are paths, and on each of them is a devil calling to it. Then he recited: This is My path, straight, so follow it, and do not follow the other paths.” Ghazali has shown one hidden path, the one by which he deceives scholars and worshippers who control their desires. Next he gives a plain path, which no one misses unless the devil forces him onto it." },
    ],
    closer: [
      { title: "The monk and the girl", body: "The Prophet told of a monk among the Israelites. The devil choked a girl and put it into her family's hearts that her cure lay with the monk. They brought her to him. He refused to take her, but they kept at him until he agreed. While she was with him for treatment, the devil made her attractive to him and kept at him. At last he committed the grave sin with her, and she became pregnant. Then he whispered: “Now you will be exposed. Her family will come. Kill her, and if they ask, say she died.” He killed her and buried her. Then the devil whispered to her family that the monk had made her pregnant, killed her and buried her. They came and asked. He said she had died. They seized him to kill him for her. The devil came to him and said: “I choked her, and I put it in her family's hearts. Obey me and I will save you.” He asked how. “Prostrate to me twice.” He prostrated twice. The devil said: “I am free of you.” This is what God says: “Like the devil, when he says to a person: disbelieve. Then when he disbelieves, he says: I am free of you.”" },
      { title: "Guard the first step", body: "Look at his tricks, Ghazali says, and how he forced the monk into these great sins. All of it came from obeying him in taking the girl for treatment, a small thing. The monk may even have thought it good and kind. Hidden desire made it look good, so he went ahead like someone keen on good. After that the matter passed out of his control, one thing dragging him into the next until he found no way out. We seek refuge in God from neglecting the beginnings of things. So the Prophet said: “Whoever grazes around a fenced pasture is about to fall into it.”" },
    ],
    distinction: ["Two kinds of the devil's paths", "The plain paths", "Roads to open sins — the mindful can close and guard them.", "The hidden paths", "Evil dressed as good — they ruin scholars and worshippers who would never sin openly."],
    misreading: "Do not read the preacher's story as a reason never to teach or advise. Ghazali's point is to stop at every concern and test it, because good work can be the devil's hidden path to status.",
    reflection: "Pick one good thing you are keen to do. Ask what the devil could gain from it, and whether that is part of why you want it.",
    audit: ["What good deed of mine might be the devil's hidden path?", "Do I stop at my concerns, or rush ahead?", "Is my devil fat or thin?", "What small first step am I taking now?"],
    nodes: ["devil", "thought", "guard"],
    model: chain("The monk's slide", "One small step, and then no way out.", [["A kindness", "He agrees to treat the girl.", "balance"], ["A desire", "The devil makes her attractive, and he sins.", "warning"], ["A cover-up", "He kills her to hide it.", "warning"], ["A prostration", "He bows to the devil to be saved — and is abandoned.", "warning"]]),
  }),
  makeChapter({
    id: 15, shortTitle: "The gates of the fortress, I", formalTitle: "The devil's ways into the heart: anger and desire, envy and greed, fullness, adornment, hoping in people, haste and money",
    overview: "The heart is a fortress, and the devil an enemy trying to get in. Guarding the heart is a duty, so knowing its gates is a duty too. The gates are a person's own traits. Ghazali begins with the great ones, each with a story. Iblis bargains with Moses and stows away on Noah's ark. He shows John his hooks, and flies round the earth the night Jesus was born.",
    thesis: "Protecting the heart from the devil is a duty on everyone, and it cannot be done without knowing where he gets in. So knowing his ways in is a duty too. His ways in are a person's own traits. The great gates are anger and desire, envy and greed, a full stomach, love of adornment, hoping in people, haste, and money beyond need.",
    moves: [
      { title: "Why the gates must be known", body: "The heart is like a fortress, and the devil is an enemy who wants to get in, own it and rule it. The fortress can only be kept by guarding its gates, entrances and breaches. No one can guard gates he does not know. Guarding the heart from the devil's whisper is a duty on every responsible person. Whatever a duty cannot be done without is also a duty. The devil cannot be driven off without knowing his ways in. So knowing them is a duty. His ways in are a person's own traits, and there are many. Ghazali points to the great gates, wide as city streets, which never grow too narrow for the devil's many armies." },
      { title: "Anger", body: "One great gate is anger and desire. Anger is the ghoul of reason. When reason's army is weak, the devil's army charges. Whenever a person is angry, the devil plays with him as a child plays with a ball. It is told that Iblis met Moses and said: “You are the one God chose for His message and spoke to. I am one of God's creatures. I sinned, and I want to repent. Ask my Lord to accept my repentance.” Moses agreed. When he had spoken with his Lord on the mountain and was about to come down, God said: “Deliver the trust.” Moses said: “Lord, Your servant Iblis wants You to accept his repentance.” God told Moses: “I grant your request. He must prostrate at Adam's grave, and he will be forgiven.”" },
      { title: "The three places Iblis gave away", body: "Moses met Iblis and told him. Iblis grew angry and proud: “I did not prostrate to him alive. Shall I prostrate to him dead?” Then he said: “Moses, you have a claim on me for asking on my behalf. So remember me at three times, and I will not destroy you in them. Remember me when you are angry: my spirit is in your heart, my eye in your eye, and I run in you like blood. When a person is angry, I blow into his nose, and he does not know what he is doing. Remember me when you meet the enemy in battle. I come to the man at that moment and remind him of his wife, his children and his family, until he runs. And never sit alone with a woman you are not closely related to. I am her messenger to you and your messenger to her. I will not stop until I have tempted you with her and her with you.” He pointed here to desire, anger and greed. Fleeing the battle is greed for this world. His refusal to prostrate to Adam dead is envy, which is his greatest way in." },
      { title: "The ball in his hands", body: "One of God's friends asked Iblis: “Show me how you beat a human being.” He said: “I take him at anger and at desire.” It is told that Iblis appeared to a monk, who asked which human trait helped him most. He said: “Sharpness of temper. When a person is sharp-tempered, we turn him over as children turn a ball.” And the devil is reported to say: “How can a human beat me? When he is pleased, I come and sit in his heart. When he is angry, I fly up and sit in his head.”" },
      { title: "Envy and greed, on the ark", body: "Another great gate is envy and greed. When a person is greedy for everything, his greed blinds and deafens him. The Prophet said: “Your love of a thing blinds and deafens.” The light of insight is what recognises the devil's ways in. When envy and greed cover it, a person cannot see. Then the devil has his chance. He makes whatever leads to the greedy man's desire look good, however wrong and shameful. When Noah boarded the ark, taking two of every kind as God commanded, he saw an old man there he did not know. Noah asked: “What brought you in?” He said: “I came in to get at your companions' hearts, so their hearts are with me while their bodies are with you.” Noah said: “Get out, enemy of God, you are cursed.” Iblis said: “There are five things by which I destroy people. I will tell you three, and not two.” God revealed to Noah: “You have no need of the three. Have him tell you the two.” Iblis said: “They are the two that never lie to me and never fail me. By them I destroy people: greed and envy. By envy I was cursed and made a devil driven out. As for greed, Adam was allowed the whole Garden except the tree, and I got what I wanted from him through greed.”" },
      { title: "A full stomach", body: "Another great gate is eating one's fill, even of pure, lawful food. Fullness strengthens desires, and desires are the devil's weapons. Iblis appeared to John son of Zechariah, hung with hooks of every kind. John asked what they were. He said: “These are the desires by which I catch people.” John asked whether there was anything for him among them. He said: “Sometimes you eat your fill, and we make you heavy for prayer and remembrance.” John asked if there was anything else. He said no. John said: “I vow to God never to fill my stomach with food.” Iblis said: “And I vow to God never to give a Muslim good advice again.” It is said that eating much has six faults. It takes the fear of God from the heart. It takes mercy for others from it, since he thinks everyone is full. It makes him heavy for worship. When he hears words of wisdom, he feels no softness. When he speaks wisdom, it does not reach people's hearts. And it stirs up illnesses." },
      { title: "Adornment, and hoping in people", body: "Another gate is love of fine furniture, clothes and houses. When the devil sees this ruling a heart, he lays eggs and hatches there. He keeps calling the person to build his house, decorate its ceilings and walls, and enlarge it. He calls him to fine clothes and mounts, and keeps him at it all his life. Once he has him there, he need not come back, since one thing leads to the next until death comes. Then he dies on the devil's path, following desire, and a bad end is feared for him. Another great gate is hoping for things from people. When that rules the heart, the devil makes putting on a show for them lovable, with every kind of display and pretence. The person hoped in becomes almost his idol. He thinks all day how to win his affection. The least of it is praising him for what he does not have, and flattering him by not commanding right or forbidding wrong. Iblis appeared to Abd Allah ibn Hanzala and said: “Keep one thing from me. Ask no one but God in hope. And watch yourself when you are angry, for I own you when you are angry.”" },
      { title: "Haste", body: "Another great gate is haste and not making sure. The Prophet said: “Haste is from the devil, and patience is from God.” God says: “The human being was created of haste.” And to His Prophet: “Do not hurry with the Quran before its revelation to you is complete.” Deeds should come after insight and knowledge, and insight needs thought and time. Haste prevents that, and in haste the devil passes off his evil unnoticed. It is told that when Jesus son of Mary was born, the devils came to Iblis and said: “The idols have woken with their heads bowed.” He said: “Something has happened. Stay here.” He flew to the ends of the earth and found nothing. Then he found Jesus born, with angels surrounding him. He came back and said: “A prophet was born last night. No female has ever conceived or given birth without my being there, except this one. Give up hope of idols being worshipped after tonight. But come at people through haste and lightness.”" },
      { title: "Money beyond need", body: "Another great gate is money: coins, goods, animals and land. Everything beyond one's food and needs is the devil's lodging. Someone who has his food has a free heart. If he found a hundred dinars on the road, desires would spring up in him, each needing another hundred. What he found is not enough; he now needs nine hundred more. Before he had a hundred, he needed nothing. Now he thinks the hundred made him rich, yet he needs nine hundred more. He wants a house to do up, a slave girl, furniture and fine clothes. Each thing calls for another that matches it, with no end. So he falls into a pit whose bottom is the depth of Hell. Thabit al-Bunani said that when the Prophet was sent, Iblis sent his devils to the Companions. They came back empty-handed, saying: “We have never been with people like these. We get something from them, then they stand up to pray and it is wiped out.” Iblis said: “Be patient with them. Perhaps God will open the world to them, and then we will get what we want.” Jesus once rested his head on a stone. Iblis passed and said: “Jesus, you have come to want the world.” Jesus threw the stone from under his head and said: “Take it, with the world.”" },
    ],
    closer: [
      { title: "Even a stone", body: "Ghazali draws the lesson of Jesus's pillow. Whoever owns a stone to rest his head on at night owns something of this world that the devil can use. A man standing to pray at night with a stone near him will keep being invited to lie down on it. Without it, the thought would never cross his mind. If a stone does this, what of soft pillows, deep mattresses and pleasant gardens? When will their owner feel eager to worship God?" },
      { title: "The gates are your own traits", body: "Every gate on this list is a trait inside the reader, not something outside. That is why Ghazali calls knowing them a duty. You cannot guard a door you have never noticed you have." },
    ],
    distinction: ["Two things Iblis never finds false", "Envy", "By it he was cursed and made a devil.", "Greed", "By it he took Adam, who had the whole Garden but one tree."],
    misreading: "Do not read these stories as tales about the devil's cleverness. Each ends by naming a gate in the reader: anger, envy, greed, fullness, adornment, hoping in people, haste, money.",
    reflection: "Go through the gates on this list and mark the one you are sure is open in you. Start guarding that one.",
    audit: ["Where does the devil sit in me — heart or head?", "What would the devil find hanging on me?", "What have I got beyond my need?", "Where am I hasty?"],
    nodes: ["devil", "guard", "anger", "appetite"],
    model: set("The great gates, first half", "Each gate is a trait of your own.", [["Anger", "He plays with you like a ball.", "warning"], ["Envy and greed", "The two that never fail him.", "warning"], ["Fullness", "Heavy for prayer and remembrance.", "warning"], ["Adornment and hoping in people", "He lays eggs and hatches.", "warning"], ["Haste", "Evil passed off unnoticed.", "warning"], ["Money beyond need", "A hundred calls for nine hundred.", "warning"]]),
  }),
  makeChapter({
    id: 16, shortTitle: "The gates of the fortress, II", formalTitle: "The devil's ways into the heart: meanness, partisanship, quarrels, questions beyond one's reach, and suspicion",
    overview: "The second half of Ghazali's list moves from the body's desires to the mind and to other people. Meanness and fear of poverty. Loud loyalty to a Companion or a school while living against its example. Getting caught up in other people's quarrels. Ordinary people poking at God's essence. And thinking badly of Muslims.",
    thesis: "The devil's gates include not only desires but loyalties, arguments and suspicions. Partisanship is especially deadly because people do not see it as a sin, so they never ask forgiveness for it. Every blameworthy trait in a person is the devil's weapon and one of his ways in.",
    moves: [
      { title: "Meanness and fear of poverty", body: "Another great gate is meanness and fear of poverty. They stop spending and charity, and call to saving up and hoarding. The painful punishment is promised to hoarders in the Quran. Khaythama ibn Abd al-Rahman said the devil says: “A human may beat me, but he will not beat me in three things. I will get him to take money wrongly, spend it wrongly, and hold it back from where it is due.” Sufyan said: “The devil has no weapon like fear of poverty. When a person accepts it from him, he takes what is false, holds back what is due, speaks from desire, and thinks badly of his Lord.”" },
      { title: "The devil's house and his snares", body: "One harm of meanness is clinging to the markets to pile up money, and the markets are the devils' nests. Abu Umama reported the Prophet: when Iblis was sent down to earth, he said: “Lord, You sent me down and made me outcast. Give me a house.” God said: “The bathhouse.” “Give me a meeting-place.” “Markets and crossroads.” “Give me food.” “Whatever is eaten without God's name.” “Give me drink.” “Every intoxicant.” “Give me a caller to prayer.” “Musical pipes.” “Give me a Quran.” “Poetry.” “Give me a writing.” “Tattoos.” “Give me speech.” “Lies.” “Give me snares.” “Women.”" },
      { title: "Loyal to Abu Bakr, far from him", body: "Another great gate is partisanship for schools and sects, spite towards opponents, and looking down on them. It ruins worshippers and wrongdoers alike. Attacking people and dwelling on their faults is part of the beast's nature in us. When the devil makes it look like the truth, and it suits one's nature, its sweetness takes over the heart. The person throws himself into it, happy, thinking he works for religion while he follows devils. You see one of them loyal to Abu Bakr while he eats the unlawful. He lets his tongue run on idle talk and lies, and does all kinds of harm. If Abu Bakr saw him, he would be his first enemy. Abu Bakr's friends are those who take his path and guard what is between their jaws. His way was to put a pebble in his mouth to stop himself speaking about what did not concern him." },
      { title: "Loyal to Ali, far from him", body: "You see another idle talker partisan for Ali. Part of Ali's way was that as caliph he wore a garment bought for three dirhams, and cut the sleeves off at the wrist. Yet you see a wrongdoer in silk, dressed up with unlawful money, claiming to love Ali. He will be Ali's first opponent on the Day of Resurrection. Suppose someone took a man's dear son, the joy of his eyes, and beat him, tore his clothes, pulled out his hair and cut it with shears. Then he claimed to love the father. How would the father see him? Religion and the law were dearer to Abu Bakr, Umar, Uthman, Ali and all the Companions than family and children, even than their own selves. Those who rush into sins are tearing the law and cutting it with the shears of desire." },
      { title: "The imams as opponents", body: "The devil makes them imagine that whoever dies loving Abu Bakr and Umar will not be touched by the Fire. He makes another imagine that if he dies loving Ali, he has nothing to fear. Yet the Prophet said to Fatima, who was part of him: “Work, for I cannot help you against God at all.” The same holds for those partisan for al-Shafii, Abu Hanifa, Malik, Ahmad and other imams. Whoever claims an imam's school and does not follow his way will have that imam as his opponent on the Day. The imam will say: “My school was acting, not talk. Talk was for the sake of acting, not for chatter. Why did you go against my deeds and my way, which was my real school and the path I took to God, and then falsely claim my school?”" },
      { title: "The schools handed over", body: "This, Ghazali says, is a huge way in for the devil, and by it he has ruined most of the world. The schools of learning have been handed to people with little fear of God, weak insight in religion, strong desire for this world, and fierce greed for followers. They could only gain followers and status through partisanship. So they kept it in their chests and never warned people of the devil's plot in it. They stood in for the devil in carrying out his plan. People kept at it and forgot the foundations of their religion. They were ruined and ruined others. May God turn to us and to them. Al-Hasan said: “We heard that Iblis said: I made sins look good to Muhammad's community, and they broke my back with asking forgiveness. So I made sins look good to them that they do not ask forgiveness for: their sectarian passions.” The cursed one spoke the truth. They do not know these lead to sins, so how would they ask forgiveness?" },
      { title: "Other people's quarrels", body: "One of the devil's great tricks is to keep a person busy with other people's disagreements and disputes, instead of with himself. Ibn Mas'ud said: “Some people sat remembering God. The devil came to make them get up and scatter, and could not. So he went to another group talking about worldly things and set them against each other. They got up and fought, though it was not them he wanted. The people remembering God got up to separate them. So they left their gathering, and that was what the devil wanted.”" },
      { title: "Questions beyond one's reach", body: "Another gate is leading ordinary people, who have not trained in knowledge, to think about God's essence and attributes, beyond what their minds can reach. He makes them doubt the root of religion, or imagine things about God that He is far above. One of them becomes an unbeliever or an innovator by it. He is delighted with what came into his chest, thinking it insight that his cleverness uncovered. The biggest fool is the one most sure of his own mind. The soundest mind belongs to the one who most suspects himself and asks scholars most. Aisha reported the Prophet: “The devil comes to one of you and says: who created you? He says: God. The devil says: then who created God? Whoever finds this should say: I believe in God and His messenger. It will go away.” The Prophet did not tell people to research this whisper. It comes to ordinary people, not scholars. Their duty is to believe, accept, and get on with their worship and living, leaving knowledge to scholars. Ghazali says an ordinary person committing adultery and theft would be better off than speaking about knowledge. Whoever talks about God and His religion without mastering knowledge falls into unbelief without knowing. He is like someone who cannot swim riding out onto the open sea." },
      { title: "Suspicion", body: "Another gate is thinking badly of Muslims. “You who believe, avoid much suspicion. Some suspicion is a sin.” Whoever judges another as bad on suspicion is pushed by the devil to backbite him. He falls short in his rights, fails to honour him, and looks down on him. He sees himself as better. All of these destroy. So the law forbids exposing oneself to suspicion. Safiyya, the Prophet's wife, visited him while he was in retreat in the mosque. When evening came she left, and he walked with her. Two men of the Ansar passed, greeted him and went on. He called them back and said: “This is Safiyya bint Huyayy.” They said: “Messenger of God, we think only good of you.” He said: “The devil runs in a person like blood in the body, and I feared he might get into you.” See how he cared for their religion, and taught his community to guard against suspicion. No learned, careful man known for religion should think: “No one thinks anything but good of someone like me.” People never look at anyone with one eye. Some look with the eye of approval, and some with the eye of anger. As the poet said, the eye of approval is too dim to see any fault, but the eye of anger shows up every flaw." },
    ],
    closer: [
      { title: "The fault-finder shows himself", body: "Whenever you see someone who thinks badly of people and hunts for faults, he is foul inside. His own foulness is seeping out, and he sees others by what he is. The believer looks for excuses; the hypocrite looks for faults. The believer's chest is clean towards all people." },
      { title: "Every blameworthy trait", body: "These are some of the devil's ways into the heart. Ghazali says he could not list them all, and this is enough to point to the rest. There is no blameworthy trait in a person that is not the devil's weapon and one of his ways in." },
    ],
    distinction: ["Two ways of looking at people", "The believer", "Looks for excuses; his chest is clean towards everyone.", "The hypocrite", "Looks for faults — and his own foulness is what he sees."],
    misreading: "Do not read the attack on partisans as an attack on loving Abu Bakr, Ali or the imams. Ghazali's charge is against claiming them while living against their example, and he says they will be such people's opponents.",
    reflection: "Think of a group or teacher you are loyal to. Ask whether they would recognise their way in how you live.",
    audit: ["Whose name do I claim, and do I follow his way?", "Do I look for excuses or for faults?", "Am I busy with others' quarrels instead of myself?", "Do I ask scholars, or trust my own cleverness?"],
    nodes: ["devil", "guard", "self"],
    model: set("The great gates, second half", "Loyalties, arguments and suspicions.", [["Meanness", "Fear of poverty, his best weapon.", "warning"], ["Partisanship", "Sins no one asks forgiveness for.", "warning"], ["Others' quarrels", "Pulled out of the gathering of remembrance.", "warning"], ["Questions beyond reach", "Who created God?", "warning"], ["Suspicion", "The fault-finder shows himself.", "warning"]]),
  }),
  makeChapter({
    id: 17, shortTitle: "Diet before medicine", formalTitle: "The remedy: whether the remembrance of God is enough to drive the devil off",
    overview: "Is saying “there is no power except by God” enough to drive the devil away? Ghazali answers with a hungry dog, a medicine taken on a full stomach, and the prayer as a touchstone. Remembrance does drive him off, as he fled Umar's path — but only from a heart that has first been emptied of what he feeds on.",
    thesis: "The real remedy is to close the gates by cleaning the heart of blameworthy traits. After that, the devil only passes by, and remembrance keeps him from even that. But remembrance works only in a heart cleaned by mindfulness. In a heart full of desire it is only talk to oneself, like medicine taken without a diet.",
    moves: [
      { title: "Close the gates first", body: "You may ask what the remedy is, and whether remembering God and saying “There is no power and no strength except by God” is enough. The heart's remedy is to close these gates by cleaning it of the blameworthy traits. That takes long to explain. This quarter of the Ihya is about curing the destructive traits, and each needs its own book. Once the roots of these traits are cut out of the heart, the devil only passes through and makes passing attempts. He does not settle. And remembrance stops even his passing through. The reality of remembrance only takes hold in a heart already built up by mindfulness and cleaned of blameworthy traits. Otherwise remembrance is just talk to oneself, with no power over the heart. It cannot push back the devil's power. So God says: “When those who are mindful are touched by a prowler from the devil, they remember, and at once they see.” He made it special to the mindful." },
      { title: "The hungry dog", body: "The devil is like a hungry dog coming towards you. If you have no bread or meat in front of you, it is chased off when you say “Go away!” Your voice alone drives it off. If you have meat in front of you and it is hungry, it goes for the meat, and words will not stop it. A heart empty of the devil's food is rid of him by remembrance alone. But when desire rules the heart, it pushes the reality of remembrance to the heart's edges. It cannot reach the heart's core, so the devil settles in the core. The devil comes to the hearts of the mindful too, not for desires, but when they are empty through forgetting to remember. When they return to remembrance, he draws back." },
      { title: "The fat devil and the thin one", body: "Abu Hurayra said: “The believer's devil and the unbeliever's devil met. The unbeliever's devil was oiled, fat and clothed. The believer's devil was thin, dishevelled, dusty and naked. The unbeliever's devil asked: why are you so thin? He said: I am with a man who says God's name when he eats, so I stay hungry. He says it when he drinks, so I stay thirsty. He says it when he dresses, so I stay naked. He says it when he oils his hair, so I stay dishevelled. The other said: but I am with a man who does none of that. So I share his food, drink and clothes.”" },
      { title: "Muhammad ibn Wasi's prayer", body: "Muhammad ibn Wasi used to say every day after the dawn prayer: “God, You have set over us an enemy who sees our faults. He and his tribe see us from where we do not see them. God, make him despair of us as You made him despair of Your mercy. Make him lose hope in us as You made him lose hope of Your pardon. Put distance between us and him as You put distance between him and Your mercy. You have power over all things.” One day Iblis appeared to him on the way to the mosque and said: “Ibn Wasi, do you know me? I am Iblis. I want you to teach no one this prayer, and I will leave you alone.” He said: “By God, I will not keep it from anyone who wants it. Do what you like.”" },
      { title: "The torch of fire", body: "Abd al-Rahman ibn Abi Layla said a devil used to come to the Prophet with a torch of fire in his hand. He stood in front of him while he prayed. He recited and sought refuge, but the devil did not go. Gabriel came and said: “Say: I take refuge in God's perfect words, which neither the righteous nor the wicked can pass beyond. From the evil of what goes into the earth and what comes out of it, what comes down from the sky and what goes up into it. From the trials of the night and the day, and from whatever knocks at night and by day, except one who knocks with good, O Merciful.” He said it, and the torch went out and the devil fell on his face. Al-Hasan said Gabriel told the Prophet that a powerful jinn was plotting against him. He taught him to recite the Verse of the Throne when he went to bed. The Prophet said: “A devil came and fought me, then fought me again. I seized him by the throat. By the One who sent me with the truth, I did not let go until I felt the coolness of his tongue's spit on my hand. If not for my brother Solomon's prayer, he would have been lying tied up in the mosque.”" },
      { title: "Umar's path", body: "The Prophet said: “Umar never takes a path but the devil takes a different path.” That is because those hearts were cleaned of the devil's pasture and food, which is desire. If you hope the devil will be driven from you by remembrance alone, as he was from Umar, you hope for the impossible. You are like someone who takes medicine without keeping a diet, his stomach busy with heavy food. He hopes it will help him as it helped someone who dieted and emptied his stomach first. Remembrance is the medicine, and mindfulness is the diet. Mindfulness empties the heart of desires. When remembrance comes down into a heart empty of everything else, the devil is driven off, as illness is driven off when medicine reaches an empty stomach. “In that is a reminder for whoever has a heart.” And whoever helps the devil with his deeds is his friend, even if he remembers God with his tongue." },
      { title: "The prayer as touchstone", body: "You may say the reports speak of remembrance driving off the devil without conditions. But most general statements in the law are limited by conditions, which the scholars have handed down. Look at yourself: hearing is not like seeing. The height of your remembrance and worship is the prayer. Watch your heart in the prayer. See how the devil pulls it to the markets, to people's accounts, to answering opponents. See how he leads you through the valleys and dangers of this world. You only remember forgotten bits of worldly business in your prayer. The devil crowds your heart most when you pray. The prayer is the touchstone of hearts: it shows their good and their bad. Prayer is not accepted from hearts stuffed with worldly desires. So the devil is not driven off, and the whispering may even grow, as medicine before a diet may make things worse. If you want to be free of the devil, keep the diet of mindfulness first, then follow it with the medicine of remembrance. The devil will flee from you as he fled from Umar." },
      { title: "Dead hearts", body: "Wahb ibn Munabbih said: “Be mindful of God, and do not curse the devil in public while being his friend in secret.” Someone said: “How strange, to disobey the One who is good to you after knowing His goodness, and obey the cursed one after knowing his rebellion.” God says: “Call on Me and I will answer you.” You call on Him and are not answered. In the same way you remember God and the devil does not flee, because the conditions of remembrance and prayer are missing. Ibrahim ibn Adham was asked why their prayers were not answered. He said: “Because your hearts are dead.” He named eight things that killed them. You knew God's right and did not fulfil it. You read the Quran and did not act on its limits. You said you loved the Prophet and did not follow his practice. You said you feared death and did not prepare for it. God said the devil is your enemy, and you agreed with him on sins. You said you feared the Fire, and wore your bodies out in it. You said you loved the Garden, and did not work for it. And when you got up from your beds, you threw your own faults behind you and spread out other people's in front of you. So you angered your Lord. How would He answer you?" },
    ],
    closer: [
      { title: "Eat the vegetable", body: "You may ask whether one devil calls to all the different sins, or different devils. Practice does not need this, Ghazali says. Busy yourself with driving off the enemy, not with his description. Eat the vegetable as it comes to you, and do not ask about the garden. He does add, though, what the reports show: they are organised armies, and each kind of sin has its own devil. The next section gives the reports." },
      { title: "Remembrance is not blamed", body: "The failure of remembrance in a full heart is not a failure of remembrance. Ghazali compares it to unanswered prayer: the promise stands, and the conditions are missing on our side." },
    ],
    distinction: ["Two hearts saying the same words", "The emptied heart", "Like a dog with no meat in front of you: one word sends it off.", "The full heart", "Like a hungry dog at the meat: words do not stop it."],
    misreading: "Do not read this section as saying remembrance is useless. Ghazali says it is the medicine, and that it drove the devil from Umar's path. His point is the order: diet first, then medicine.",
    reflection: "Watch your heart in your next prayer, as Ghazali asks. Note where the devil takes it. That is where his food is.",
    audit: ["What meat is in front of me when I say “Go away”?", "Is my devil fat or thin?", "Where did my heart go in my last prayer?", "Which of Ibrahim ibn Adham's eight is true of me?"],
    nodes: ["remember", "devil", "guard"],
    model: pair("Medicine and diet", "Why remembrance works for some and not for others.", [["Mindfulness (the diet)", "Empties the heart of the desires the devil feeds on.", "support"], ["Remembrance (the medicine)", "Drives him off — once the stomach is empty.", "support"]]),
  }),
  makeChapter({
    id: 18, shortTitle: "Armies unseen", formalTitle: "The devils' many kinds, the angels who guard, and how devil and angel appear to people",
    overview: "The devils are organised armies, each kind of sin with its own devil, and the angels are many too. Ghazali gathers the reports: Iblis's five sons, the one hundred and sixty angels set over each believer, the bargain Adam and Iblis each struck with God. Then he explains how a devil or an angel can be seen, and why what is seen always matches what it stands for.",
    thesis: "Different sins have different devils, as different effects have different causes. Against them God has set many angels. Angels and devils have true forms that only prophets see. Those shown the unseen usually see a likeness, and a likeness from the unseen always matches its meaning: the ugly shows as ugly and the beautiful as beautiful.",
    moves: [
      { title: "Iblis's five sons", body: "Mujahid said Iblis has five sons, each put in charge of one part of his work. Thabr is in charge of calamities: he orders wailing, tearing at clothes, slapping cheeks and the cries of the age of ignorance. Al-A'war is in charge of adultery; he orders it and makes it look good. Masut is in charge of lying. Dasim goes home with a man and makes him find fault with his family and grow angry with them. Zalanbur is in charge of the market, and because of him people there keep wronging each other. The devil of the prayer is called Khinzab, and the devil of ablution al-Walhan. Many reports speak of this." },
      { title: "A hundred and sixty angels", body: "Just as the devils are many, so are the angels. Ghazali has explained in the Book of Gratitude why each angel has its own single task. Abu Umama reported the Prophet: “A hundred and sixty angels are set over the believer to defend him from what he cannot defend himself against. Seven of them guard the sight alone. They fend off devils from him as flies are fended off a bowl of honey on a summer day. If they were shown to you, you would see devils on every plain and mountain, each with his hand stretched out and his mouth open. If a person were left to himself for the blink of an eye, the devils would snatch him away.”" },
      { title: "Adam's bargain and Iblis's", body: "Jabir reported that when Adam came down to earth, he said: “Lord, You have put enmity between me and this one. If You do not help me against him, I cannot stand against him.” God said: “No child will be born to you without an angel set over him.” Adam said: “Lord, give me more.” God said: “I repay a bad deed with one like it, and a good deed with ten, and as much more as I wish.” “Lord, give me more.” “The door of repentance is open as long as the spirit is in the body.” Iblis said: “Lord, this servant You have honoured over me — if You do not help me against him, I cannot stand against him.” God said: “No child will be born to him without a child born to you.” “Lord, give me more.” “You will run in them like blood, and take their chests as houses.” “Lord, give me more.” God said: “Rally against them your horsemen and your foot soldiers” — to the end of the verse, “and the devil promises them only deception.”" },
      { title: "Three kinds of jinn, three of humans", body: "Abu al-Darda reported the Prophet: “God created the jinn in three kinds. One kind is snakes, scorpions and crawling things of the earth. One kind is like wind in the air. And one kind has reward and punishment. God created humans in three kinds. One kind is like cattle. As God says, they have hearts they do not understand with, eyes they do not see with, and ears they do not hear with. They are like cattle, or even further astray. One kind has human bodies and devils' spirits. And one kind will be in God's shade on the Day of Resurrection, when there is no shade but His.” Ayyub ibn Yunus said he had heard that some of the children of humans are born from the jinn and grow up among them." },
      { title: "What Iblis told John", body: "Wuhayb ibn al-Ward said Iblis appeared to John son of Zechariah and said: “I want to give you advice.” John said: “I have no need of your advice. But tell me about the children of Adam.” He said: “To us they are three kinds. The first is the hardest on us. We come at one of them until we tempt him and get hold of him. Then he rushes to ask forgiveness and repent, and spoils everything we gained from him. We come back, and he comes back. We never give up on him, and we never get what we want. We are worn out by him. The second kind are in our hands like a ball in your children's hands. We turn them as we please; they have spared us the effort. The third kind are like you: protected. We can do nothing with them.”" },
      { title: "Gabriel in his true form", body: "You may ask how the devil appears to some people and not others. When he is seen in a form, is it his real form or a likeness? If it is real, how is he seen in different forms, or in two places at once by two people? Ghazali answers that the angel and the devil each have a real form. Their real forms are seen only by the lights of prophethood. The Prophet saw Gabriel in his true form only twice. He asked Gabriel to show himself as he really was. Gabriel promised to meet him at al-Baqi, and appeared to him at Hira, filling the horizon from east to west. He saw him again in his true form on the night of the Ascension, at the Lote Tree of the Furthest Boundary. Mostly he saw him in human form, often in the form of Dihya al-Kalbi, a man with a handsome face." },
      { title: "The frog on the shoulder", body: "Usually those shown the unseen, the people of the heart, see a likeness of the devil's form. The devil takes a likeness for such a person while he is awake. He sees it with his eyes and hears its words with his ears. It stands in for the real form, as it does in dreams for most good people. The one shown things while awake has reached a level where the senses' busyness with the world no longer blocks what others see in sleep. So he sees awake what others see asleep. It is told from Umar ibn Abd al-Aziz that a man asked his Lord to show him where the devil sits in a person's heart. In sleep he saw a man's body like crystal, the inside visible from the outside. He saw the devil as a frog sitting on the left shoulder, between shoulder and ear. It had a long thin snout that it had put in through the left shoulder to the heart, whispering to it. When the man remembered God, it drew back. Someone shown things awake saw the devil as a dog crouched over a carcass, calling people to it. The carcass was a likeness of this world." },
      { title: "Why likenesses do not lie", body: "This is like seeing his real form, because the heart has two faces. One faces the unseen kingdom, and is the way in for inspiration and revelation. The other faces the visible world. When a truth appears on the face towards the unseen, its trace shines on the face towards the visible, because the two are joined. What appears on the visible side can only be an image in the imagination, for the whole visible world is images. When the image comes from looking at the outside of the visible world, it may not match the meaning. You may see a person with a beautiful face and a foul, ugly inside, for the visible world is full of deception. But an image that forms in the imagination from the unseen kingdom shining on the heart's secret always copies the quality and matches it. So an ugly meaning is only seen in an ugly form. The devil is seen as a dog, a frog or a pig, and the angel in a beautiful form. So in dreams a monkey or a pig points to a foul person, and a sheep to someone with a clean heart. So it is with all dream interpretation. These are wonderful secrets of the heart, Ghazali says, and do not belong in a book on practice." },
    ],
    closer: [
      { title: "What to take from it", body: "The point, Ghazali says, is to believe that the devil is shown to the people of hearts, and so is the angel. Sometimes it is by likeness, as in sleep, and sometimes by the real form. Most often it is a likeness that copies the meaning. It is a likeness of the meaning, not the meaning itself, but it is truly seen with the eye. Only the one shown it sees it, not those around him, just as only the sleeper sees his dream." },
      { title: "Not left alone", body: "The report of the angels round the believer is Ghazali's counterweight to the devils' armies. If a person were left to himself for the blink of an eye, the devils would snatch him. He is not left to himself." },
    ],
    distinction: ["Two kinds of form", "From the visible world", "May deceive — a beautiful face over a foul inside.", "From the unseen", "Always matches the meaning — the ugly as ugly, the beautiful as beautiful."],
    misreading: "Do not read the frog and the dog as decoration. Ghazali says an image from the unseen always tells the truth about what it stands for. That is why a dog over a carcass is a true picture of this world.",
    reflection: "Remember that seven angels guard your sight alone. Think about what you ask them to guard it from, and what you let past them.",
    audit: ["Which of Iblis's sons has most work in me?", "Which of the three kinds of human am I?", "Do I ruin the devil's gains by quick repentance?", "What would my heart look like as crystal?"],
    nodes: ["devil", "angel", "unseen"],
    model: pair("Adam's bargain and Iblis's", "What each was given.", [["Adam", "An angel over every child; good deeds tenfold; repentance open until death.", "support"], ["Iblis", "A child for every child; running in them like blood; horsemen and foot soldiers — and a promise that is only deception.", "warning"]]),
  }),
  makeChapter({
    id: 19, shortTitle: "Which thoughts are forgiven", formalTitle: "What a person is held to account for among the heart's whispers, concerns, thoughts and aims, and what is forgiven",
    overview: "The texts seem to pull two ways. Some reports say what a person tells himself is forgiven. Some verses say God will call to account what is in the self. Ghazali untangles it by laying out the heart's steps before any act: the passing thought, the pull of nature, the heart's judgment, and the firm resolve. Then he says which are forgiven and which are not.",
    thesis: "The passing thought and the pull of nature are not chosen, so they are forgiven. The heart's judgment is held against a person when it is chosen. Firm resolve is held against him — but if he drops it for fear of God, it is written as a good deed. The heart is the root, and is more answerable than the limbs.",
    moves: [
      { title: "Texts that seem to clash", body: "This is a subtle question, Ghazali says, and verses and reports seem to conflict. Only the finest scholars can join them. The Prophet said: “My community is forgiven what they tell themselves, as long as they do not speak of it or act on it.” Abu Hurayra reported that God tells the recording angels: “When My servant means to do a bad deed, do not write it. If he does it, write it as one bad deed. When he means to do a good deed and does not do it, write it as a good deed. If he does it, write it as ten.” Another version says a good deed done is written up to seven hundred times. All this points to forgiveness. But God says: “Whether you show what is in yourselves or hide it, God will call you to account for it.” And: “Hearing, sight and the heart — all of these will be questioned.” That makes the heart's work like the work of hearing and sight. And: “Whoever hides testimony, his heart is sinful.” And: “God will call you to account for what your hearts have earned.”" },
      { title: "Four steps before the act", body: "The truth here, Ghazali says, cannot be seen without laying out the heart's work from its start to the act on the limbs. First comes the passing thought. Say the thought comes to a man that a woman is behind him on the road, and if he turned he would see her. Second, a wish to look stirs. That is desire moving in his nature, born of the first thought. Ghazali calls it the pull of nature, and the first step the self's talk. Third, the heart judges that it should be done: that he should look. Nature may pull, but will does not rise until the things holding it back fall away, such as shame or fear. That judgment comes from reason, and is called belief. Fourth, he firms up his resolve to turn and decides on it. That is called meaning to act, intention and aim." },
      { title: "How resolve firms up", body: "This resolve may start weak. But if the heart listens to the first thought until its pull on the self lasts long, the resolve grows firm and becomes a settled will. Once the will is settled, he may regret it and drop the act. Or he may be distracted by something and forget it. Or something may block him and make the act impossible. So there are four states of the heart before the limbs act. First is the passing thought, which is the self's talk. Then come the pull, the judgment and the resolve." },
      { title: "What is forgiven", body: "The passing thought is not held against a person, because it is not chosen. Nor is the pull and the stirring of desire, since they are not chosen either. These are what the Prophet meant by “what they tell themselves”. The self's talk means thoughts that stir in the self without any resolve to act. Resolve is not called the self's talk. Uthman ibn Maz'un said to the Prophet: “My self tells me to divorce Khawla.” He said: “Easy — marriage is part of my way.” “My self tells me to castrate myself.” “Easy — the castration of my community is steady fasting.” “My self tells me to become a monk.” “Easy — the monasticism of my community is striving in God's cause and the pilgrimage.” “My self tells me to give up meat.” “Easy — I love it. If I found it I would eat it, and if I asked God, He would feed me with it.” These were thoughts without resolve, which is why he consulted the Prophet." },
      { title: "The judgment, and the resolve", body: "The third step, the heart's judgment that the thing should be done, can be forced or chosen, and states differ. What is chosen is held against a person. What is forced is not. The fourth step, the resolve to act, is held against him. But if he does not act, it is looked at. If he left it for fear of God and regret for meaning it, a good deed is written for him. His resolve was a bad deed, and his holding back and fighting himself are a good deed. Meaning to act in line with nature shows complete heedlessness of God. Holding back by fighting against nature needs great strength. His effort against his nature is work for God, and harder than his effort in agreeing with the devil. So the good deed is written, because his effort to hold back outweighed his resolve to act. If the act was blocked by something, or he left it for an excuse, not for fear of God, a bad deed is written against him. His resolve was a chosen act of the heart." },
      { title: "Left for My sake", body: "The proof of this detail is a report in the Sahih. The Prophet said: “The angels say: Lord, there is Your slave, meaning to do a bad deed — and He sees him better. God says: watch him. If he does it, write it as one like it. If he leaves it, write it for him as a good deed. He left it only for My sake.” So where the report says “if he does not do it”, it means he leaves it for God. If he resolves on something foul and it becomes impossible for some reason, or he forgets it, how could a good deed be written? The Prophet said: “People will be raised according to their intentions.” It is certain that someone who resolves at night to kill a Muslim or commit adultery in the morning, and dies that night, dies insisting on it. He is raised on his intention, though he meant a bad deed and did not do it." },
      { title: "Both swords in the Fire", body: "The decisive proof is the Prophet's saying: “When two Muslims meet with their swords, the killer and the killed are both in the Fire.” He was asked: “That is the killer — but why the one killed?” He said: “Because he wanted to kill his companion.” This plainly shows he became one of the people of the Fire by his will alone, though he was killed wrongly. So how can anyone think God does not hold intention and resolve to account? Every resolve that is chosen is held against a person, unless he wipes it out with a good deed. Undoing the resolve by regret is a good deed, so a good deed is written. Missing the aim because something got in the way is not a good deed." },
      { title: "Beyond one's power", body: "Passing thoughts, the self's talk and the stirring of wanting are not chosen, and holding them against a person would be asking what cannot be borne. Then the verse came down: “Whether you show what is in yourselves or hide it, God will call you to account.” Some Companions came to the Prophet and said: “We have been given more than we can bear. One of us tells himself things he would not want to settle in his heart, and then he is called to account for it!” He said: “Are you going to say what the Jews said: we hear and disobey? Say: we hear and obey.” They said: “We hear and obey.” Then God sent relief a year later: “God does not burden any soul beyond its capacity.” So whatever of the heart's work is beyond a person's capacity is what he is not held to account for." },
    ],
    closer: [
      { title: "The heart is the root", body: "How could a person not be held to account for the heart's own works: pride, vanity, showing off, hypocrisy, envy and all the foulness of the heart? Hearing, sight and the heart will all be questioned — for what is chosen. If the eye falls on a woman not closely related without choosing, he is not held to account. If he follows it with a second look, he is, because he chose. The heart's thoughts are the same, and the heart is even more answerable, since it is the root. The Prophet said, “Mindfulness is here,” pointing to his heart. God says: “Neither their meat nor their blood reaches God, but your mindfulness reaches Him.” The Prophet said: “Sin is what pricks the heart.” And: “Goodness is what the heart rests in, even if people give you rulings and rulings.”" },
      { title: "Judged by the heart", body: "So, Ghazali says, if a heart decides a thing is required and is wrong, it is rewarded for acting on it. Someone who thinks he has purified himself must pray. If he prays and then remembers he had not done ablution, he is rewarded for acting. If he remembers first and prays anyway, he is punished. Suppose a man finds a woman in his bed and thinks she is his wife. He does not sin by lying with her, even if she is a stranger to him. If he thinks she is a stranger and lies with her, he sins, even if she is his wife. All of this looks to the heart, not the limbs." },
    ],
    distinction: ["Two resolves that were not carried out", "Left for fear of God", "The resolve was a bad deed; the holding back is a good deed — written as a good deed.", "Blocked by chance", "Nothing was fought; the chosen resolve stands — written as a bad deed."],
    misreading: "Do not read “what you tell yourselves is forgiven” as covering everything in the heart. Ghazali limits it to the passing thought and the pull you did not choose. Chosen judgment and resolve are held to account.",
    reflection: "Think of something you meant to do wrong and did not do. Ask whether you left it for God, or whether something just got in the way.",
    audit: ["Which of the four steps am I at with my strongest temptation?", "Did I leave my last bad plan for God, or by chance?", "Do I take the second look?", "What does my heart rest in?"],
    nodes: ["thought", "resolve", "action", "heart"],
    model: chain("Four steps before the act", "Ghazali's example: a woman behind you on the road.", [["The passing thought", "She is there; if I turned I would see her. Forgiven.", "balance"], ["The pull of nature", "A wish to look stirs. Forgiven.", "balance"], ["The heart's judgment", "I should look. Held to account if chosen.", "warning"], ["The resolve", "I will turn. Held to account — unless dropped for fear of God.", "warning"]]),
  }),
  makeChapter({
    id: 20, shortTitle: "Can whispering be silenced?", formalTitle: "Whether whispering can be cut off completely by the remembrance of God",
    overview: "Scholars who watched their hearts disagreed on what remembrance does to whispering, in five views. Ghazali says all five are right, each about one kind of whisper. Then he admits the hard truth: freedom from the devil for a moment or an hour is possible, but for a lifetime it is impossible. Even the Prophet threw away a garment and a gold ring that had drawn his eye in prayer.",
    thesis: "Each of the five views describes one kind of whisper. A whisper that dresses up the truth vanishes before the light of faith. One that stirs desire is pushed back but not silenced. One that is merely a wandering thought comes and goes with remembrance. Freedom for an hour is near; freedom for a lifetime is impossible.",
    moves: [
      { title: "Five views", body: "Scholars who watch hearts and study their qualities split into five groups on this. One group said whispering is cut off by remembering God, because the Prophet said: “When God is remembered, he draws back.” Drawing back means falling silent. A second said it does not vanish at root, but runs in the heart without effect. A heart filled with remembrance is screened from being moved by it. It is like someone busy with a worry, who hears speech pass his ears without taking it in. A third said neither the whisper nor its effect goes, but its hold over the heart goes, so it whispers from far off and weakly." },
      { title: "The spinning ball, and four eyes", body: "A fourth group said whispering vanishes for an instant with remembrance, and remembrance vanishes for an instant with whispering. They take turns so fast that they seem to run side by side. They are like a ball with scattered dots on it: spin it quickly, and the dots join into lines. These pointed out that the drawing back is in the reports, and yet we see whispering alongside remembrance, so this must be how. A fifth group, including al-Muhasibi, said whispering and remembrance run side by side in the heart without a break. A person can see two things at once with his two eyes. So the heart can carry two things. The Prophet said: “Everyone has four eyes. Two are in his head, to see the affairs of his world. Two are in his heart, to see the affairs of his religion.”" },
      { title: "All five are right", body: "The correct view, Ghazali says, is that all five are sound, but each falls short of taking in every kind of whisper. Each group looked at one kind and spoke about it. Whispering has kinds. The first kind dresses things up with the truth. The devil may say: “Will you give up enjoying pleasures? Life is long, and holding back from desires all your life is very painful.” Then the person remembers God's great right, His great reward and punishment. He says to himself: “Holding back from desires is hard, but holding out in the Fire is harder, and it must be one or the other.” When he remembers God's promise and threat and renews his faith and certainty, the devil draws back and runs. He cannot say the Fire is easier than holding back from sins, or that sin does not lead to the Fire. His faith in God's Book pushes that away. So the whisper is cut off." },
      { title: "The whisper of vanity", body: "It is the same when the devil whispers vanity about his deeds: “What servant knows God as you do, and worships Him as you do? How high your place is with God!” Then the person remembers that his knowledge, his heart and the limbs he works and knows with were all created by God. So what is there to be proud of? The devil draws back, because he cannot say this is not from God. Knowledge and faith push it away. This kind of whisper is cut off completely for those who know and see by the light of faith." },
      { title: "Stirred desire, and wandering thoughts", body: "The second kind works by stirring and exciting desire. If the person knows for certain that the thing is a sin, the devil draws back from stirring that would move the desire, though not from stirring altogether. If it is only probably a sin, the stirring may keep its effect, so that it must be fought off. The whisper is there, but pushed back and not in control. The third kind is mere passing thoughts: recalling pressing affairs, thinking of other things in the prayer, for example. When a person turns to remembrance, it may be pushed off for a while and come back, and go and come back. Remembrance and whisper take turns. Or they may run together, so that his understanding holds both the meaning of the recitation and those thoughts, as if in two places in the heart." },
      { title: "Two units without a stray thought", body: "It is very unlikely that this kind is driven off completely, so that nothing comes to mind. But it is not impossible. The Prophet said: “Whoever prays two units without telling himself anything of this world is forgiven his past sins.” If it were not possible, he would not have said it. It is only possible in a heart that love has taken over, until it is like one infatuated. We see a man whose heart is full of an enemy who hurt him think, for two units of prayer and more, about arguing with his enemy. Nothing but his enemy comes to mind. The one sunk in love may talk with his beloved in his heart and sink into his thought, so that nothing else comes to mind. If someone spoke to him, he would not hear. If someone walked in front of him, it would be as if he did not see. If this can happen from fear of an enemy or greed for money and status, why not from fear of the Fire and longing for the Garden? But it is rare, because faith in God and the Last Day is weak." },
      { title: "An hour, not a lifetime", body: "Looking over these kinds of whisper, you see that each view has a point in its own place. In short: freedom from the devil for a moment or an hour is not far off. But freedom from him for a long life is very far off, and impossible in fact. If anyone could be free of the devil's whispers through passing thoughts and stirred wanting, it would be the messenger of God. It is told that he looked at the border of his garment in prayer. When he finished, he threw the garment off and said: “It distracted me from the prayer. Take it to Abu Jahm and bring me his plain wrap.” He had a gold ring on his hand. He looked at it while on the pulpit and threw it away, saying: “A look at it, and a look at you.” That was the devil's whispering, stirring the pleasure of looking at a gold ring and a garment's border. It was before gold was forbidden, which is why he had worn it." },
      { title: "Honey and flies", body: "So whispering about worldly goods and money is only cut off by throwing them away and parting from them. As long as someone owns anything beyond his need, even one dinar, the devil will not leave his prayer alone. He will whisper about the dinar. How to keep it, and what to spend it on? How to hide it so no one knows, or show it off? Someone may sink his claws into this world and hope to be free of the devil. He is like someone who plunges into honey and thinks the flies will not land on him. That is impossible. This world is a great door for the devil's whispering. And he has not one door but many." },
    ],
    closer: [
      { title: "The devil's ladder", body: "A sage said: the devil comes to a person through sins. If he refuses, he comes as an adviser, until he throws him into an innovation. If he refuses, he orders him to be over-strict and harsh, until he forbids what is not forbidden. If he refuses, he makes him doubt his ablution and prayer, until he pushes him out of knowledge. If he refuses, he makes good deeds light for him, so that people see him as patient and chaste and their hearts lean to him. Then he grows vain of himself, and by that the devil destroys him. There the devil presses hardest, because it is the last step. He knows that if the person gets past it, he escapes him into the Garden." },
      { title: "The Prophet's garment", body: "Ghazali tells the story of the garment and the ring to set the measure, not to lower the Prophet. If a look at a border could reach even him, no one should expect to be free of whispering for a lifetime. The Prophet's answer was to throw away the thing at once." },
    ],
    distinction: ["Two kinds of freedom from the devil", "For an hour", "Near and possible — two units of prayer with no stray thought.", "For a lifetime", "Impossible in fact — even the Prophet threw away what caught his eye."],
    misreading: "Do not read the admission that whispering never fully stops as despair. Ghazali's point is that a lasting whisper does not prove remembrance has failed; it shows which kind of whisper you face, and what answers it.",
    reflection: "Next time a thought keeps coming back in prayer, ask which of the three kinds it is. Then use the answer that fits it.",
    audit: ["Which kind of whisper troubles me most?", "What do I own that the devil talks to me about in prayer?", "Have I ever prayed two units with no stray thought?", "Which rung of the devil's ladder am I on?"],
    nodes: ["remember", "devil", "thought"],
    model: chain("Three kinds of whisper", "Why each of the five views is right about something.", [["Dressed as truth", "Cut off completely by the light of faith.", "support"], ["Stirred desire", "Pushed back, but still there to be fought.", "balance"], ["Wandering thoughts", "Come and go with remembrance; rarely silenced.", "warning"]]),
  }),
  makeChapter({
    id: 21, shortTitle: "How quickly the heart turns", formalTitle: "How fast the heart turns, and how hearts divide in changing and holding firm",
    overview: "The book ends on movement. The heart is a target struck from every side, and never left alone. The Prophet swore by the Turner of hearts and prayed to be kept firm. Ghazali sorts hearts into three: one at peace, one abandoned, and one fought over, where the devil and the angel argue their case in turn. Behind it all stands God's decree.",
    thesis: "The heart is always turning, pulled between angels and devils. Most hearts pass from one party to the other; lasting firmness on either side is rare. A heart cleaned by mindfulness draws good upon good. A heart full of desire draws the devil in. The middle heart is won by whichever side its traits resemble.",
    moves: [
      { title: "Never left alone", body: "The heart is surrounded by the traits Ghazali has described, and traces and states pour into it through the gates he has named. It is like a target struck all the time from every side. When something strikes it and changes it, something else strikes it from another side with the opposite, and its state changes. If a devil comes down and calls it to desire, an angel comes down and turns it away. If one devil drags it to one evil, another drags it to another. If one angel draws it to one good, another draws it to another. Sometimes it is pulled between two angels, sometimes between two devils, sometimes between an angel and a devil. It is never left alone. God says: “We turn their hearts and their eyes.”" },
      { title: "The Turner of hearts", body: "Because the Prophet saw God's wonderful work in the heart and its turning, he used to swear by it: “No, by the Turner of hearts!” He often prayed: “O Turner of hearts, keep my heart firm on Your religion.” They asked: “Are you afraid, messenger of God?” He said: “What makes me safe, when the heart is between two of the fingers of the Merciful, who turns it as He wills?” Another version says: “If He wills to keep it straight, He keeps it straight; if He wills to make it swerve, He makes it swerve.” He gave three pictures. “The heart is like a sparrow, turning over every hour.” “The heart in its turning is like a pot when it comes to a full boil.” “The heart is like a feather in open desert, turned over and over by the winds.” Only those who watch their states with God know these turnings and God's wonderful work in them." },
      { title: "The first heart: at peace", body: "The first heart is built up by mindfulness, purified by training, and cleaned of foul traits. Good thoughts spark in it from the treasuries of the unseen. Reason turns to think about the thought, to learn the fine points of its good and the secrets of its benefit. The light of insight uncovers it, and reason judges that it must be done and urges the heart to do it. The angel looks at the heart and finds it good in substance, pure through mindfulness, lit by reason and filled with the lights of knowledge. He sees it fit to be his home and landing place. Then he backs it with armies it cannot see, and guides it to other good, so good draws on good, without end. God points to it: “As for the one who gives and is mindful and believes in the best, We will ease his way to ease.”" },
      { title: "A black ant on a dark night", body: "In such a heart the light of the lamp shines from the niche of Lordship. Not even hidden idolatry stays hidden in it — the kind subtler than a black ant crawling on a black rock on a dark night. Nothing is hidden from this light, and none of the devil's plots get past it. The devil stands and whispers fine-sounding words to deceive, and it pays no attention. Once this heart is cleaned of the destructive traits, it soon fills with the saving ones. Ghazali will describe them: gratitude, patience, fear, hope, poverty, doing without, love, contentment, longing, trust, reflection, self-examination and more. This is the heart God has turned His face to. It is the heart at peace: “Truly, in the remembrance of God hearts find rest,” and “O self at peace”." },
      { title: "The second heart: abandoned", body: "The second heart is abandoned: stuffed with desire, dirty with blameworthy traits and foulness. The devils' doors are open in it and the angels' doors shut. Its evil begins when a thought of desire sparks and stirs in it. The heart looks to reason as judge, asking for a ruling and the right course. But reason has grown used to serving desire and is at home with it. It has long been busy finding tricks for desire and helping it. So the self takes over and helps, and the chest opens to desire and spreads its darkness, because reason's army is held back from defending it. The devil's rule grows stronger as his room grows with the spreading of desire. He comes at it with fine show, deception and false hopes, whispering fine-sounding words." },
      { title: "Smoke in the eyes", body: "Then the power of faith in God's promise and threat grows weak, and the light of certainty and fear of the next world fades. A dark smoke rises from desire into the heart and fills its corners until its lights go out. Reason becomes like an eye whose lids are filled with smoke: it cannot see. That is what desire does when it takes over the heart. The heart can no longer pause and look. Even if a preacher showed it the truth and made it hear, it would be blind to understanding and deaf to hearing. Desire stirs, the devil strikes, and the limbs move as desire wants. So the sin comes out from the unseen world into the visible, by God's decree and measure. “Have you seen the one who takes his desire as his god? Will you be his guardian? Or do you think most of them hear or understand? They are only like cattle — no, further astray.”" },
      { title: "Abandoned in one place", body: "Many a heart is like this only with some desires. A man may be careful about some things, but when he sees a beautiful face, he cannot control his eye and heart. His reason flies off and his heart loses its hold. Or he cannot control himself where status, leadership and pride are at stake, and has no firmness left when their causes appear. Or he cannot control himself when angry, whenever he is belittled or one of his faults is mentioned. Or he cannot control himself when he can take a coin, but throws himself at it like one crazed with love, forgetting honour and mindfulness. All of this is the smoke of desire rising to the heart until it goes dark and its lights go out. Then the light of shame, honour and faith goes out, and he works for what the devil wants." },
      { title: "The third heart: the devil's case", body: "The third heart is one where thoughts of desire appear and call it to evil, and a thought of faith follows and calls it to good. The self, with its desire, rises to support the evil thought. Desire grows stronger and makes enjoyment and comfort look good. Reason rises for the good thought and pushes back desire. It calls desire's act ugly and ignorant. It compares desire to a beast and a wild animal, rushing at evil without caring for the end. The self leans to reason's advice. Then the devil charges at reason and strengthens desire's call. He says: “What is this cold squeamishness? Why hold back from what you want and hurt yourself? Do you see anyone in your time going against his desire or giving up his aim? Will you leave the world's pleasures for them to enjoy, and fence yourself in, deprived, miserable and worn out, while everyone laughs at you? Do you want to rise above so-and-so, when they did what you want and did not hold back? Don't you see that famous scholar doesn't guard against this? If it were bad, he would stop.” And the self leans towards the devil and turns to him." },
      { title: "The angel's case", body: "Then the angel charges at the devil and says: “Who is ruined except the one who follows the pleasure of the moment and forgets the end? Will you settle for a small pleasure and give up the pleasure of the Garden and its bliss for ever? Does the pain of holding back from your desire feel heavy, and the pain of the Fire not? Are you fooled by people's heedlessness of themselves, their following their desires and helping the devil? Other people's sin will not lighten the punishment of the Fire for you. Suppose you were out on a blazing summer day, with everyone standing in the sun, and you had a cool house. Would you stand with them, or seek your own escape? How can you go against people for fear of the sun's heat, and not for fear of the Fire's heat?” Then the self follows the angel's words. The heart keeps swinging between the two armies, pulled between the two parties, until whatever it is more fit for wins." },
    ],
    closer: [
      { title: "Which side wins", body: "If the traits in the heart are mostly the devilish ones Ghazali has named, the devil wins. The heart leans to its own kind among the devil's parties and turns from God's party. What leads it far from God runs on its limbs by prior decree. If the angelic traits are stronger, it does not listen to the devil's tempting, urging it to the present world and making light of the next. It leans to God's party, and obedience shows on its limbs by what was decreed. The believer's heart is between two fingers of the Merciful, meaning between the pull of these two armies. Turning and moving from one party to the other is the usual state. Lasting firmness with the angels' party or the devil's is rare on both sides. Obedience and sin come out from the treasuries of the unseen into the visible world through the treasury of the heart. When they appear, they are signs by which the people of hearts know what was decreed." },
      { title: "The Guide and the One who leaves astray", body: "Whoever was created for the Garden has the means of obedience made easy for him. Whoever was created for the Fire has the means of sin made easy for him. Bad companions are set over him, and the devil's wisdom is thrown into his heart. With kinds of wisdom he fools the foolish: “God is merciful, so don't worry.” “Nobody fears God, so don't be different.” “Life is long, so wait and repent tomorrow.” He promises them repentance and holds out forgiveness, and ruins them by God's permission. “Whomever God wants to guide, He opens his chest to Islam. Whomever He wants to leave astray, He makes his chest tight and constricted, as if climbing into the sky.” He is the Guide and the One who leaves astray. He does what He wills; no one can turn back His ruling. He created the Garden and people for it, and uses them in obedience. He created the Fire and people for it, and uses them in sin. And He told people the signs: “The righteous are in bliss, and the wicked are in Hellfire.” He is reported as saying: “These are in the Garden, and I do not mind. These are in the Fire, and I do not mind.” Exalted is God, the true King. He is not asked about what He does, and they are asked. Ghazali ends the book here, saying the full account of the heart's wonders does not belong in a book on practice. He has given what is needed to reach the deep roots of practice, for readers not content with the outside." },
    ],
    distinction: ["Two hearts facing the same thought", "The heart at peace", "Reason examines the thought, sees its good, and the angel adds good upon good.", "The abandoned heart", "Reason is consulted, but it already serves desire, so it supplies the excuses."],
    misreading: "Do not read the three hearts as fixed labels for people. Ghazali says turning from party to party is the usual state, and firmness on either side is rare. Any label only describes today.",
    reflection: "Ask which of the three hearts describes you today, not in general, and notice that the question has to be asked that way.",
    audit: ["Which way is my heart turning today?", "Where do I lose control, even though I am careful elsewhere?", "Which case won my last inner argument — the devil's or the angel's?", "Do I pray to be kept firm, as the Prophet did?"],
    nodes: ["steady", "heart", "angel", "devil"],
    model: chain("One thought, two hearts", "What happens after a thought arrives.", [["A thought arrives", "A good idea, or a selfish one, comes to the heart.", "balance"], ["The heart asks reason", "It turns to reason for a ruling.", "balance"], ["Habit answers", "Reason looks honestly, or finds ways to get what was already wanted.", "warning"], ["It grows", "Good draws more good, or the smoke thickens until the lights go out.", "warning"]]),
  }),
];

