// data.ts supplies the six nodes for the heart and its forces (heart, intellect, appetite,
// anger, senses, action). The rest of the book's vocabulary is defined here so the frozen
// /isfahan and /world routes keep the vocabulary they were built with.
const book21ExtraNodes: ConceptNode[] = [
  ["self", "The self", "The enemy, or you", "One word for two things: the gathering of anger and desire that must be fought, and the real person — at peace, blaming, or urging evil."],
  ["knowledge", "Knowledge", "The picture arriving", "The true form of a thing appearing in the heart. Rational or religious, worldly or otherworldly, learned or inspired."],
  ["mirror", "The mirror", "The book's main picture", "The heart reflects the truth of things. Sins blacken it, obedience polishes it, and five causes stop a picture showing."],
  ["veil", "The veil", "What stands between", "A curtain between the heart and the truth: rust, a belief taken on trust, busyness, or the devils hovering round the heart."],
  ["unseen", "The unseen kingdom", "Wider than heaven and earth", "The world seen only by insight: the Preserved Tablet, the angels, and the Garden as wide as the heart's knowing."],
  ["inspiration", "Inspiration", "Knowledge from within", "Knowledge thrown into the heart without learning. Revelation is the same, with the angel seen; learning is the same, with the veil lifted by effort."],
  ["thought", "The passing thought", "Where every act begins", "It crosses the heart unbidden, stirs a wish, then resolve, then intention, then the limbs. On its own it is forgiven."],
  ["angel", "The angel", "The touch of good", "The cause of a thought that calls to good. Angels guard the believer and land in a heart cleaned of desire."],
  ["devil", "The devil", "The touch of evil", "The cause of a thought that calls to evil. His weapons are desire and lust, and his ways in are a person's own traits."],
  ["guard", "Guarding the gates", "A duty that follows from a duty", "Guarding the heart is required, and cannot be done without knowing its gates, so knowing them is required too."],
  ["remember", "Remembrance", "The medicine", "Remembering God drives the devil off — from a heart first emptied of what he feeds on. Mindfulness is the diet."],
  ["resolve", "Resolve", "Where blame begins", "A chosen, firm intention. Held to account — unless dropped for fear of God, when it is written as a good deed."],
  ["steady", "Turning and holding firm", "Between two fingers", "The heart turns faster than a pot at the boil. Most hearts pass between the two parties; lasting firmness is rare."],
].map(([id, label, kicker, description]) => ({ id, label, kicker, description, position: `node-${id}` }));

